# Global variable to store genre mappings per scraper
genre_mapping_cache = {}

def load_genre_mapping():
    """Load genre mapping from scrapper_genre_mapping.json"""
    global genre_mapping_cache
    try:
        mapping_path = os.path.join('var', 'config', 'scrapper_genre_mapping.json')
        if os.path.exists(mapping_path):
            with open(mapping_path, 'r', encoding='utf-8') as f:
                genre_mapping_cache = json.load(f)
            print(f"✅ Genre mapping loaded from {mapping_path}")
        else:
            print(f"⚠️  Genre mapping file not found at {mapping_path}, genre mapping disabled")
            genre_mapping_cache = {}
    except Exception as e:
        print(f"❌ Error loading genre mapping: {e}")
        genre_mapping_cache = {}

def map_genre(scraper_name, genre_text):
    """
    Map genre text using the scraper-specific mapping.
    
    Args:
        scraper_name: Name of the scraper (e.g., 'screenscraper', 'igdb', 'launchbox', 'mobygames')
        genre_text: Original genre text from the scraper
    
    Returns:
        Mapped genre text, or original if no mapping found
    """
    if not genre_text or not genre_mapping_cache:
        return genre_text
    
    # Normalize scraper name (lowercase)
    scraper_name = scraper_name.lower()
    
    # Get scraper mapping
    scraper_data = genre_mapping_cache.get(scraper_name, {})
    if not isinstance(scraper_data, dict):
        return genre_text
    
    mapping = scraper_data.get('map', {})
    if not mapping:
        return genre_text
    
    # Try exact match only - if not found, return original text
    if genre_text in mapping:
        mapped = mapping[genre_text]
        print(f"🔧 DEBUG map_genre: Found mapping for '{genre_text}' -> '{mapped}'")
        return mapped
    else:
        print(f"🔧 DEBUG map_genre: No mapping found for '{genre_text}', returning original")
        return genre_text

def process_screenscraper_genres(genre_names):
    """
    Process ScreenScraper genres: map all genres and join them.
    
    Args:
        genre_names: List of genre names from ScreenScraper API
    
    Returns:
        String with genres joined by ', ', after mapping
    """
    if not genre_names:
        return None
    
    # Map each genre
    mapped_genre_names = []
    for genre_name in genre_names:
        original_genre = genre_name
        mapped_genre = map_genre('screenscraper', genre_name)
        if original_genre != mapped_genre:
            print(f"🔧 DEBUG Genre Mapping: Original='{original_genre}' -> Mapped='{mapped_genre}'")
        mapped_genre_names.append(mapped_genre)
    
    # Join mapped genres with ', '
    return ', '.join(mapped_genre_names)

def process_launchbox_genres(genre_text):
    """
    Process LaunchBox genres: split by semicolon, map each genre, and join with ', '.
    
    Args:
        genre_text: Genre string from LaunchBox (may contain semicolons)
    
    Returns:
        Comma-separated string of mapped genres
    """
    if not genre_text:
        return ''
    
    # Split by semicolon
    genre_list = [g.strip() for g in str(genre_text).split(';') if g.strip()]
    
    if not genre_list:
        return ''
    
    # Map each genre
    mapped_genres = []
    for genre in genre_list:
        mapped = map_genre('launchbox', genre)
        if mapped:
            mapped_genres.append(mapped)
    
    # Join with ', ' (comma and space)
    return ', '.join(mapped_genres)

def process_igdb_genres(genre_text):
    """
    Process IGDB genres: split by comma, map each genre, and join with ', '.
    
    Args:
        genre_text: Genre string from IGDB (may contain commas)
    
    Returns:
        Comma-separated string of mapped genres
    """
    if not genre_text:
        return ''
    
    # Split by comma
    genre_list = [g.strip() for g in str(genre_text).split(',') if g.strip()]
    
    if not genre_list:
        return ''
    
    # Map each genre
    mapped_genres = []
    for genre in genre_list:
        mapped = map_genre('igdb', genre)
        if mapped:
            mapped_genres.append(mapped)
    
    # Join with ', ' (comma and space)
    return ', '.join(mapped_genres)

def process_mobygames_genres(genre_value):
    """
    Process MobyGames genres: handle list or comma-separated string, map each genre, and join with ', '.
    
    Args:
        genre_value: Genre value from MobyGames (can be a list or comma-separated string)
    
    Returns:
        Comma-separated string of mapped genres
    """
    if not genre_value:
        return ''
    
    # If it's a list, join with comma first
    if isinstance(genre_value, list):
        genre_text = ', '.join(str(g) for g in genre_value if g)
    else:
        genre_text = str(genre_value)
    
    if not genre_text:
        return ''
    
    # Split by comma
    genre_list = [g.strip() for g in genre_text.split(',') if g.strip()]
    
    if not genre_list:
        return ''
    
    # Map each genre, but skip genres that map to "Various" and avoid duplicates
    mapped_genres = []
    seen_mapped = set()
    for genre in genre_list:
        mapped = map_genre('mobygames', genre)
        if mapped and mapped != 'Various' and mapped not in seen_mapped:
            mapped_genres.append(mapped)
            seen_mapped.add(mapped)
    
    # Join with ', ' (comma and space)
    return ', '.join(mapped_genres)

