def _run_launchbox_scraper_simplified(system_name, selected_games=None, enable_partial_match_modal=False, force_download=False, selected_fields=None, overwrite_text_fields=False, task=None):
    """Simplified LaunchBox scraper that runs in main thread using global cache"""
    try:
        print(f"🔧 DEBUG: Starting simplified LaunchBox scraper for system: {system_name}")
        
        if task:
            task.update_progress(f"🚀 Starting LaunchBox scraping for {system_name}")
        
        # Ensure global cache is loaded
        global global_metadata_cache_loaded, global_metadata_cache
        if not global_metadata_cache_loaded:
            print("🔄 Loading global metadata cache...")
            if task:
                task.update_progress(f"📚 Loading LaunchBox metadata cache...")
            load_metadata_cache()
            if task:
                task.update_progress(f"✅ LaunchBox metadata cache loaded")
        
        print(f"🔧 DEBUG: Global cache loaded: {global_metadata_cache_loaded}")
        print(f"🔧 DEBUG: Global cache type: {type(global_metadata_cache)}")
        print(f"🔧 DEBUG: Global cache length: {len(global_metadata_cache) if global_metadata_cache else 0}")
        
        # Get system configuration
        mapping_config, system_platform_mapping = load_launchbox_config()
        current_system_platform = system_platform_mapping.get(system_name, {}).get('launchbox', system_name)
        
        print(f"🔧 DEBUG: Mapping config: {mapping_config}")
        print(f"🔧 DEBUG: Selected fields: {selected_fields}")
        
        print(f"🔧 DEBUG: Using platform: {current_system_platform}")
        
        # Get gamelist path
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return {'success': False, 'error': f'Gamelist not found: {gamelist_path}'}
        
        # Parse games from gamelist
        all_games = parse_gamelist_xml(gamelist_path)
        if not all_games:
            return {'success': False, 'error': 'No games found in gamelist'}
        
        print(f"🔧 DEBUG: Found {len(all_games)} games in gamelist")
        
        # Filter games if selection is provided (but keep original list for saving)
        games = all_games
        if selected_games:
            games = [g for g in all_games if g.get('path', '') in selected_games]
            print(f"🔧 DEBUG: Filtered to {len(games)} selected games")
        
        # Process games
        stats = {
            'total_games': len(games),
            'processed_games': 0,
            'matched_games': 0,
            'updated_games': 0
        }
        
        matched_rom_paths = []
        
        if task:
            task.update_progress(f"🎯 Processing {len(games)} games for LaunchBox metadata")
        
        for i, game_data in enumerate(games):
            game_name = game_data.get('name', '')
            if not game_name:
                continue
            
            print(f"🔧 DEBUG: Processing game {i+1}/{len(games)}: {game_name}")
            
            # Update progress
            if task:
                progress_percent = int(((i + 1) / len(games)) * 100)
                task.update_progress(f"🔍 Processing {game_name} ({i+1}/{len(games)})", progress_percentage=progress_percent, current_step=i+1, total_steps=len(games))
            
            # Check if game already has a LaunchBox ID
            existing_launchboxid = game_data.get('launchboxid')
            if existing_launchboxid:
                # Use existing LaunchBox ID directly - look up in global cache
                launchboxid = existing_launchboxid
                print(f"🔧 DEBUG: Using existing LaunchBox ID: {launchboxid}")
            else:
                # No existing LaunchBox ID - find one using name lookup
                launchboxid = find_launchboxid_from_partionned_index_directmatch(
                    game_name, 
                    current_system_platform, 
                    existing_launchboxid=None
                )
            
            if launchboxid:
                stats['matched_games'] += 1
                print(f"🔧 DEBUG: Found LaunchBox ID: {launchboxid}")
                
                # Get game data from cache (ensure string format since global cache keys are strings)
                launchboxid_str = str(launchboxid)
                print(f"🔧 DEBUG: Looking up LaunchBox ID '{launchboxid_str}' in global cache")
                print(f"🔧 DEBUG: Global cache has {len(global_metadata_cache)} entries")
                print(f"🔧 DEBUG: Sample cache keys: {list(global_metadata_cache.keys())[:5]}")
                best_match = get_cached_game_data(launchboxid_str)
                print(f"🔧 DEBUG: get_cached_game_data returned: {type(best_match)}, data: {best_match}")
                if best_match:
                    # Update game data in the original all_games list
                    # Find the corresponding game in all_games by path
                    game_path = game_data.get('path', '')
                    # Extract ROM filename for parentheses preservation
                    rom_filename = os.path.splitext(os.path.basename(game_path))[0] if game_path else ''
                    for j, original_game in enumerate(all_games):
                        if original_game.get('path', '') == game_path:
                            print(f"🔧 DEBUG: Calling update_game_data_from_launchbox with overwrite_text_fields={overwrite_text_fields}, selected_fields={selected_fields}, rom_filename={rom_filename}")
                            updated = update_game_data_from_launchbox(original_game, best_match, mapping_config, overwrite_text_fields, selected_fields, rom_filename)
                            print(f"🔧 DEBUG: update_game_data_from_launchbox returned: {updated}")
                            if updated:
                                stats['updated_games'] += 1
                            # Always add to matched_rom_paths if we found a LaunchBox ID (for image downloads)
                            matched_rom_paths.append(game_path)
                            break
            else:
                print(f"🔧 DEBUG: No match found for: {game_name}")
            
            stats['processed_games'] += 1
        
        # Update final progress
        if task:
            task.update_progress(f"✅ Processed {stats['processed_games']} games, matched {stats['matched_games']}, updated {stats['updated_games']}")
        
        # Save updated gamelist (always save, even if no games were updated, to ensure consistency)
        print("💾 Saving updated gamelist...")
        save_gamelist_xml(gamelist_path, all_games)
        if stats['updated_games'] > 0:
            print(f"✅ Updated {stats['updated_games']} games in gamelist")
        else:
            print("💾 Gamelist saved (no games updated)")
        
        # Notify clients that gamelist was updated (refresh grid)
        try:
            notify_gamelist_updated(system_name, len(all_games), updated_count=stats['updated_games'])
            print(f"🔔 Notified clients of gamelist update: {len(all_games)} total games, {stats['updated_games']} updated")
        except Exception as e:
            print(f"⚠️ Warning: Failed to notify clients of gamelist update: {e}")
        
        return {
            'success': True,
            'stats': stats,
            'gamelist_path': gamelist_path,
            'rom_paths': matched_rom_paths,
            'system_name': system_name
        }
        
    except Exception as e:
        error_msg = f'Error in simplified LaunchBox scraper: {str(e)}'
        print(f"❌ ERROR: {error_msg}")
        import traceback
        traceback.print_exc()
        return {'success': False, 'error': error_msg}

def find_launchboxid_from_partionned_index_directmatch(game_name, target_platform, existing_launchboxid=None):
    """Find LaunchBox ID using direct lookup in partitioned indexes only"""
    try:
        print(f"🔧 DEBUG: find_launchboxid_from_partionned_index_directmatch called with game_name: {game_name}, target_platform: {target_platform}")
        
        # Load partitioned indexes if not already loaded
        global global_launchbox_partition_index, global_launchbox_indexes_loaded
        if not global_launchbox_indexes_loaded:
            print("🔄 Loading LaunchBox partitioned indexes...")
            load_launchbox_partitioned_indexes()
        
        partition_index = global_launchbox_partition_index
        
        if not partition_index:
            return None
        
        # Note: existing_launchboxid is now handled in the main loop, not here
        
        # Check if target platform exists in indexes
        if target_platform not in partition_index:
            return None
        
        # First try: Direct match with parentheses
        normalized_with_parens = normalize_game_name(game_name, remove_paranthesis=False, remove_articles=False)
        if normalized_with_parens and normalized_with_parens in partition_index[target_platform]:
            launchboxid = partition_index[target_platform][normalized_with_parens]
            print(f"🔧 DEBUG: Found LaunchBox ID {launchboxid} with parentheses match")
            return launchboxid
        
        # Fallback: Try without parentheses (search in the same index)
        normalized_no_parens = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=False)
        if normalized_no_parens and normalized_no_parens != normalized_with_parens and normalized_no_parens in partition_index[target_platform]:
            launchboxid = partition_index[target_platform][normalized_no_parens]
            print(f"🔧 DEBUG: Found LaunchBox ID {launchboxid} without parentheses match (fallback)")
            return launchboxid
        
        print(f"🔧 DEBUG: No LaunchBox ID found for '{game_name}' on platform '{target_platform}'")
        return None
        
    except Exception as e:
        print(f"❌ ERROR in find_launchboxid_from_partionned_index_directmatch: {e}")
        return None

def update_game_data_from_launchbox(game_data, best_match, mapping_config, overwrite_text_fields=False, selected_fields=None, rom_filename=None):
    """Update game data with LaunchBox information"""
    try:
        updated = False
        
        # Update text fields
        print(f"🔧 DEBUG: Processing {len(mapping_config)} mapping entries: {list(mapping_config.items())}")
        print(f"🔧 DEBUG: best_match keys: {list(best_match.keys())}")
        print(f"🔧 DEBUG: selected_fields: {selected_fields}")
        print(f"🔧 DEBUG: overwrite_text_fields: {overwrite_text_fields}")
        for launchbox_field, gamelist_field in mapping_config.items():
            field_exists = launchbox_field in best_match
            field_has_value = field_exists and best_match[launchbox_field]
            print(f"🔧 DEBUG: Checking field {launchbox_field}->{gamelist_field}: exists={field_exists}, has_value={field_has_value}")
            if field_exists and field_has_value:
                old_value = game_data.get(gamelist_field, '')
                new_value = best_match[launchbox_field]
                
                # Special handling for name field - preserve parentheses content from ROM filename
                if launchbox_field == 'Name' and rom_filename:
                    # Extract parentheses content from ROM filename
                    import re
                    parens_match = re.search(r'\(([^)]+)\)', rom_filename)
                    if parens_match:
                        parens_content = parens_match.group(0)  # Includes parentheses: "(USA)"
                        # Add parentheses content to the name if not already present
                        if parens_content not in new_value:
                            new_value = f"{new_value} {parens_content}"
                        print(f"🔧 DEBUG: Added parentheses from ROM filename: '{best_match[launchbox_field]}' -> '{new_value}'")
                
                # Special handling for CommunityRating - normalize to 0-5 scale with 2 decimals
                if launchbox_field == 'CommunityRating' and gamelist_field == 'rating':
                    new_value = normalize_rating(new_value, 5)
                
                # Special handling for Genre/Genres - split by semicolon, map each, join with comma
                if launchbox_field in ['Genre', 'Genres'] and gamelist_field == 'genre':
                    new_value = process_launchbox_genres(new_value)
                    print(f"🔧 DEBUG: Processed LaunchBox genres: '{best_match[launchbox_field]}' -> '{new_value}'")
                
                # Check if we should update this field
                should_update = False
                if selected_fields:
                    # Check if the LaunchBox field (not gamelist field) is in selected_fields
                    # selected_fields contains LaunchBox field names like "Name", "Developer", etc.
                    # Special handling for Genre/Genres - accept either one
                    is_selected = launchbox_field in selected_fields
                    if not is_selected and launchbox_field == 'Genre':
                        # Also check for "Genres" (plural) if "Genre" (singular) is in mapping
                        is_selected = 'Genres' in selected_fields
                    elif not is_selected and launchbox_field == 'Genres':
                        # Also check for "Genre" (singular) if "Genres" (plural) is in mapping
                        is_selected = 'Genre' in selected_fields
                    
                    should_update = is_selected and (overwrite_text_fields or not old_value)
                    print(f"🔧 DEBUG: Field {launchbox_field}->{gamelist_field}: selected={is_selected}, overwrite={overwrite_text_fields} (type: {type(overwrite_text_fields)}), old_value='{old_value}', empty={not old_value}, should_update={should_update}")
                else:
                    # Update all fields based on overwrite setting or empty field check
                    should_update = overwrite_text_fields or not old_value
                    print(f"🔧 DEBUG: Field {launchbox_field}->{gamelist_field}: overwrite={overwrite_text_fields} (type: {type(overwrite_text_fields)}), old_value='{old_value}', empty={not old_value}, should_update={should_update}")
                
                if should_update and old_value != new_value:
                    game_data[gamelist_field] = new_value
                    updated = True
                    print(f"🔧 DEBUG: Updated {gamelist_field}: '{old_value}' -> '{new_value}'")
                elif should_update and old_value == new_value:
                    print(f"🔧 DEBUG: Field {gamelist_field} already has correct value: '{old_value}'")
                else:
                    print(f"🔧 DEBUG: Skipping field {gamelist_field}: old='{old_value}', new='{new_value}'")
        
        # Update launchboxid
        if 'DatabaseID' in best_match:
            old_launchboxid = game_data.get('launchboxid', '')
            new_launchboxid = best_match['DatabaseID']
            if old_launchboxid != new_launchboxid:
                game_data['launchboxid'] = new_launchboxid
                updated = True
                print(f"🔧 DEBUG: Updated launchboxid: '{old_launchboxid}' -> '{new_launchboxid}'")
        
        return updated
        
    except Exception as e:
        print(f"❌ ERROR updating game data: {e}")
        return False


def _scraping_result_listener(result_q):
    """Receive results from worker and finalize tasks and notify clients."""
    while True:
        try:
            res = result_q.get()
            if res is None:
                break
            # Streamed progress update from worker
            if isinstance(res, dict) and res.get('type') == 'progress':
                msg_task_id = res.get('task_id')
                message = res.get('message', '')
                curr = res.get('current_step')
                total = res.get('total_steps')
                pct = res.get('progress_percentage')
                stats_update = res.get('stats') or {}
                if msg_task_id and msg_task_id in tasks:
                    try:
                        t = tasks[msg_task_id]
                        if t.status == TASK_STATUS_RUNNING:
                            # keep stats in sync for UI counters
                            if stats_update:
                                t.update_stats(stats_update)
                            t.update_progress(message, progress_percentage=pct, current_step=curr, total_steps=total)
                    except Exception:
                        pass
                # Do NOT finalize or advance queue for progress updates
                continue
            

            # Final result from worker
            task_id = res.get('task_id')
            ok = res.get('ok', False)
            data = res.get('data', {})
            if task_id and task_id in tasks:
                if ok:
                    stats = data.get('stats', {})
                    tasks[task_id].update_stats(stats)
                    tasks[task_id].complete(True)
                    gl = data.get('gamelist_path')
                    if gl:
                        system_name = os.path.basename(os.path.dirname(gl))
                        notify_gamelist_updated(system_name, stats.get('total_games', 0), 0, stats.get('updated_games', 0))
                    # create image download task if any
                    rom_paths = data.get('rom_paths') or []
                    print(f"🔧 DEBUG: Scraping result - gl: {gl}, rom_paths: {len(rom_paths) if rom_paths else 0}")
                    if gl and rom_paths:
                        try:
                            # Get username from the original scraping task
                            original_task = tasks[task_id]
                            username = getattr(original_task, 'username', 'Unknown')
                            
                            print(f"🔧 DEBUG: Creating image download task for {len(rom_paths)} games")
                            add_task_to_queue('image_download', {
                                'system_name': os.path.basename(os.path.dirname(gl)),
                                'data': {
                                    'selected_games': rom_paths,
                                    'force_download': original_task.data.get('force_download', False),
                                    'selected_fields': original_task.data.get('selected_fields')
                                }
                            }, username=username)
                            tasks[task_id].update_progress(f"🖼️  Image download task created for {len(rom_paths)} matched games")
                            print(f"🔧 DEBUG: Image download task created successfully")
                        except Exception as _e:
                            print(f"Failed to enqueue image task: {_e}")
                    else:
                        print(f"🔧 DEBUG: No image download task created - gl: {gl}, rom_paths: {len(rom_paths) if rom_paths else 0}")
                else:
                    # If worker reports a cooperative stop and provided a saved gamelist, still notify and mark as stopped
                    # Check for stopped flag at both top level and in data (for different worker implementations)
                    is_stopped = res.get('stopped') or data.get('stopped')
                    gamelist_path = res.get('gamelist_path') or data.get('gamelist_path')
                    
                    if is_stopped and gamelist_path:
                        stats = res.get('stats', {}) or data.get('stats', {})
                        tasks[task_id].update_stats(stats)
                        gl = gamelist_path
                        system_name = os.path.basename(os.path.dirname(gl)) if gl else None
                        if system_name:
                            notify_gamelist_updated(system_name, stats.get('total_games', 0), 0, stats.get('updated_games', 0))
                        # mark as completed (stopped by user) so UI can refresh
                        tasks[task_id].complete(True, "Task stopped by user (partial save)")
                    elif is_stopped:
                        # Task was stopped but no gamelist was saved - still mark as completed
                        stats = res.get('stats', {}) or data.get('stats', {})
                        if stats:
                            tasks[task_id].update_stats(stats)
                        tasks[task_id].complete(True, "Task stopped by user")
                    else:
                        tasks[task_id].complete(False, res.get('error', 'Unknown error'))

            # Now that current task is finalized, advance the queue
            process_next_queued_task()
        except Exception as e:
            print(f"Result listener error: {e}")
            continue

def is_task_stopped():
    """Check if the current task has been stopped by the user"""
    global current_task_id, task_stop_event
    # Check both the global stop event and the task status
    if task_stop_event.is_set():
        return True
    if current_task_id and current_task_id in tasks:
        return tasks[current_task_id].status != TASK_STATUS_RUNNING
    return False

def reset_task_stop_event():
    """Reset the global task stop event"""
    global task_stop_event
    task_stop_event.clear()



# Task management system with file-based logging
import uuid
import json
from datetime import datetime
import html

def fix_over_escaped_xml_entities(text):
    """Fix over-escaped XML entities like &amp;amp;amp; -> &"""
    if not isinstance(text, str):
        return text
    
    # Keep applying html.unescape until no more changes
    original = text
    while True:
        unescaped = html.unescape(original)
        if unescaped == original:
            break
        original = unescaped
    
    return original
# Task storage and management
tasks = {}  # task_id -> task_info
task_queue = []
current_task_id = 0

def load_existing_tasks_from_logs():
    """Load existing tasks from log files on server startup"""
    global tasks
    
    if not os.path.exists(LOGS_DIR):
        return
    
    print(f"🔄 Loading existing tasks from log files in {LOGS_DIR}...")
    
    for filename in os.listdir(LOGS_DIR):
        if filename.endswith('.log'):
            task_id = filename.replace('.log', '')
            
            # Skip if task already exists in memory
            if task_id in tasks:
                continue
            
            log_file_path = os.path.join(LOGS_DIR, filename)
            try:
                # Create a Task object from the log file
                task = Task.__new__(Task)  # Create instance without calling __init__
                task.id = task_id
                task.log_file = log_file_path
                
                # Read the log file to extract task information
                with open(log_file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                
                # Parse task type and username from log content
                task.type = 'unknown'
                task.username = 'Unknown'
                for line in content.split('\n'):
                    if line.startswith('Type: '):
                        task.type = line.replace('Type: ', '').strip()
                    elif line.startswith('User: '):
                        task.username = line.replace('User: ', '').strip()
                # Parse task data (including system_name) from header
                try:
                    for line in content.split('\n'):
                        if line.startswith('Data: '):
                            data_str = line.replace('Data: ', '').strip()
                            task.data = json.loads(data_str) if data_str and data_str != 'None' else {}
                            break
                except Exception:
                    task.data = {}
                
                # Parse start time from log content
                task.start_time = None
                for line in content.split('\n'):
                    if line.startswith('Task started: '):
                        try:
                            start_str = line.replace('Task started: ', '').strip()
                            task.start_time = datetime.fromisoformat(start_str).timestamp()
                        except:
                            pass
                        break
                
                # Parse end time and status from log content
                task.end_time = None
                task.status = TASK_STATUS_IDLE
                task.error_message = None
                
                for line in content.split('\n'):
                    if line.startswith('Task ended: '):
                        try:
                            end_str = line.replace('Task ended: ', '').strip()
                            task.end_time = datetime.fromisoformat(end_str).timestamp()
                        except:
                            pass
                    elif line.startswith('Task stopped: '):
                        try:
                            end_str = line.replace('Task stopped: ', '').strip()
                            task.end_time = datetime.fromisoformat(end_str).timestamp()
                            task.status = TASK_STATUS_ERROR
                            task.error_message = "Task stopped by user"
                        except:
                            pass
                    elif line.startswith('Status: '):
                        status_str = line.replace('Status: ', '').strip()
                        if status_str in [TASK_STATUS_COMPLETED, TASK_STATUS_ERROR, TASK_STATUS_STOPPED, TASK_STATUS_IDLE]:
                            task.status = status_str
                        elif 'stopped' in status_str.lower():
                            task.status = TASK_STATUS_STOPPED
                        elif 'completed' in status_str.lower():
                            task.status = TASK_STATUS_COMPLETED
                
                # Parse progress data from JSON lines in log file
                task.progress = []
                task.stats = {}
                task.progress_percentage = 0
                task.total_steps = 0
                task.current_step = 0
                task.data = task.data or {}
                
                # Parse final task data from log file
                try:
                    with open(log_file_path, 'r', encoding='utf-8') as f:
                        for line in f:
                            line = line.strip()
                            if line.startswith('Final Status: '):
                                task.status = line.replace('Final Status: ', '').strip()
                            elif line.startswith('Progress: '):
                                progress_str = line.replace('Progress: ', '').replace('%', '').strip()
                                try:
                                    task.progress_percentage = int(progress_str)
                                except ValueError:
                                    pass
                            elif line.startswith('Current Step: '):
                                try:
                                    task.current_step = int(line.replace('Current Step: ', '').strip())
                                except ValueError:
                                    pass
                            elif line.startswith('Total Steps: '):
                                try:
                                    task.total_steps = int(line.replace('Total Steps: ', '').strip())
                                except ValueError:
                                    pass
                            elif line.startswith('System: '):
                                system_name = line.replace('System: ', '').strip()
                                if system_name != 'N/A':
                                    task.data['system_name'] = system_name
                            elif line.startswith('User: '):
                                task.username = line.replace('User: ', '').strip()
                            elif line.startswith('Stats: '):
                                stats_str = line.replace('Stats: ', '').strip()
                                try:
                                    task.stats = json.loads(stats_str)
                                except Exception:
                                    pass
                except Exception:
                    pass
                
                # Calculate duration if both times are available
                if task.start_time and task.end_time:
                    task.duration = task.end_time - task.start_time
                else:
                    task.duration = 0
                
                # Add to tasks dictionary
                tasks[task_id] = task
                print(f"  ✅ Loaded task {task_id} ({task.type}) - {task.status}")
                
            except Exception as e:
                print(f"  ❌ Error loading task {task_id}: {e}")
    
    print(f"✅ Loaded {len(tasks)} existing tasks from log files")

# Task status constants
TASK_STATUS_IDLE = 'idle'
TASK_STATUS_RUNNING = 'running'
TASK_STATUS_COMPLETED = 'completed'
TASK_STATUS_ERROR = 'error'
TASK_STATUS_STOPPED = 'stopped'
TASK_STATUS_QUEUED = 'queued'
TASK_STATUS_WAITING_CONFIRMATION = 'waiting_confirmation'

# Logs directory
LOGS_DIR = 'var/task_logs'
os.makedirs(LOGS_DIR, exist_ok=True)

class Task:
    def __init__(self, task_type, task_data=None, username=None):
        self.id = str(uuid.uuid4())
        self.type = task_type
        self.status = TASK_STATUS_IDLE
        self.progress = []
        self.stats = {}
        self.start_time = None
        self.end_time = None
        self.error_message = None
        self.data = task_data or {}
        self.username = username or 'Unknown'
        self.progress_percentage = 0
        self.total_steps = 0
        self.current_step = 0
        self.grid_refresh_needed = False
        self.log_file = os.path.join(LOGS_DIR, f"{self.id}.log")

        
        # Initialize log file
        with open(self.log_file, 'w') as f:
            f.write(f"Task started: {datetime.now().isoformat()}\n")
            f.write(f"Type: {task_type}\n")
            f.write(f"User: {self.username}\n")
            f.write(f"Data: {json.dumps(task_data, indent=2) if task_data else 'None'}\n")
            f.write("-" * 80 + "\n\n")



    
    def update_progress(self, message, progress_percentage=None, current_step=None, total_steps=None):
        """Update task progress and write to log file"""
        # Update progress tracking
        if progress_percentage is not None:
            self.progress_percentage = progress_percentage
        if current_step is not None:
            self.current_step = current_step
        if total_steps is not None:
            self.total_steps = total_steps
        
        # Only log if message is provided
        if message is not None:
            timestamp = datetime.now().strftime('%H:%M:%S')
            log_entry = f"[{timestamp}] {message}"
            
            self.progress.append(log_entry)
            
            # Write to log file
            try:
                with open(self.log_file, 'a', encoding='utf-8') as f:
                    f.write(log_entry + '\n')
                        
            except Exception as e:
                print(f"Error writing to log file {self.log_file}: {e}")

            # Keep only last 1000 messages in memory
            if len(self.progress) > 1000:
                self.progress = self.progress[-1000:]
    
    def log_message(self, message):
        """Log a message to the task log without updating progress"""
        timestamp = datetime.now().strftime('%H:%M:%S')
        log_entry = f"[{timestamp}] {message}"
        
        self.progress.append(log_entry)
        
        # Write to log file
        try:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(log_entry + '\n')
                    
        except Exception as e:
            print(f"Error writing to log file {self.log_file}: {e}")
        
        # Keep only last 1000 messages in memory
        if len(self.progress) > 1000:
            self.progress = self.progress[-1000:]
    
    def update_stats(self, stats):
        """Update task statistics"""
        self.stats.update(stats)
    
    def start(self):
        """Start the task"""
        global task_stop_event
        # Reset the global stop event when starting a new task
        task_stop_event.clear()
        self.status = TASK_STATUS_RUNNING
        self.start_time = time.time()
        # Prune old tasks (keep last 30)
        try:
            cleanup_old_tasks(max_tasks=30)
        except Exception as e:
            print(f"Task cleanup error: {e}")
        self.update_progress("Task started")
    
    def stop(self):
        """Stop the task"""
        self.status = TASK_STATUS_STOPPED
        self.end_time = time.time()
        self.error_message = "Task stopped by user"
        self.update_progress("Task stopped by user")
        
        # Write final status to log file
        try:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(f"\nTask stopped: {datetime.now().isoformat()}\n")
                f.write(f"Status: {self.status}\n")
                f.write(f"Duration: {self.end_time - self.start_time:.2f} seconds\n")
        except Exception as e:
            print(f"Error writing final status to log file {self.log_file}: {e}")

    
    def complete(self, success=True, error_message=None):
        """Complete the task"""
        self.end_time = time.time()
        if success:
            self.status = TASK_STATUS_COMPLETED
            self.progress_percentage = 100
            self.update_progress("Task completed successfully")
        else:
            self.status = TASK_STATUS_ERROR
            self.error_message = error_message
            self.update_progress(f"Task failed: {error_message}")
        
        # Write final status to log file
        try:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(f"\nTask ended: {datetime.now().isoformat()}\n")
                f.write(f"Status: {self.status}\n")
                f.write(f"Duration: {self.end_time - self.start_time:.2f} seconds\n")
                
                # Write final task data for persistence
                f.write(f"Final Status: {self.status}\n")
                f.write(f"Progress: {self.progress_percentage}%\n")
                f.write(f"Current Step: {self.current_step}\n")
                f.write(f"Total Steps: {self.total_steps}\n")
                f.write(f"System: {self.data.get('system_name') if self.data else 'N/A'}\n")
                f.write(f"User: {self.username}\n")
                f.write(f"Stats: {json.dumps(self.stats)}\n")
                
        except Exception as e:
            print(f"Error writing final status to log file {self.log_file}: {e}")
        
        # Mark that grid refresh is needed for this task type
        if self.type in ['scraping', 'screenscraper_scraping', 'media_scan', 'image_download', 'youtube_download', 'rom_scan', '2d_box_generation', 'template_box_generation', 'logo_generation', 'import_medias']:
            self.grid_refresh_needed = True
        
        # Clear current task and start next queued task
        global current_task_id
        current_task_id = 0
        process_next_queued_task()

    
    def to_dict(self):
        """Convert task to dictionary for JSON serialization"""
        return {
            'id': self.id,
            'type': self.type,
            'status': self.status,
            'progress': self.progress,
            'stats': self.stats,
            'start_time': self.start_time,
            'end_time': self.end_time,
            'error_message': self.error_message,
            'data': self.data,
            'username': self.username,
            'progress_percentage': self.progress_percentage,
            'total_steps': self.total_steps,
            'current_step': self.current_step,
            'grid_refresh_needed': getattr(self, 'grid_refresh_needed', False),
            'duration': self.end_time - self.start_time if self.end_time and self.start_time else None
        }

    def to_dict_lightweight(self):
        """Convert task to lightweight dictionary for main grid (excludes heavy fields)"""
        return {
            'id': self.id,
            'type': self.type,
            'status': self.status,
            'stats': self.stats,
            'start_time': self.start_time,
            'end_time': self.end_time,
            'error_message': self.error_message,
            'username': self.username,
            'progress_percentage': self.progress_percentage,
            'total_steps': self.total_steps,
            'current_step': self.current_step,
            'grid_refresh_needed': getattr(self, 'grid_refresh_needed', False),
            'duration': self.end_time - self.start_time if self.end_time and self.start_time else None,
            # Include essential data fields needed for grid refresh
            'data': {
                'system_name': self.data.get('system_name') if self.data else None
            } if self.data and self.data.get('system_name') else None
            # NOTE: Explicitly excluding 'progress' field to reduce payload size
        }

def create_task(task_type, task_data=None):
    """Create a new task"""
    # Get current user from Flask-Login
    username = 'Unknown'
    try:
        from flask_login import current_user
        if current_user and current_user.is_authenticated:
            username = current_user.username
    except Exception:
        pass
    
    task = Task(task_type, task_data, username)
    tasks[task.id] = task
    return task

def get_task(task_id):
    """Get a task by ID"""
    return tasks.get(task_id)

def get_all_tasks():
    """Get all tasks"""
    return {task_id: task.to_dict() for task_id, task in tasks.items()}

def get_all_tasks_lightweight():
    """Get all tasks in lightweight format (excludes heavy fields)"""
    return {task_id: task.to_dict_lightweight() for task_id, task in tasks.items()}

def get_task_log(task_id):
    """Get the log content for a specific task"""
    task = get_task(task_id)
    if not task:
        return None
    
    try:
        with open(task.log_file, 'r', encoding='utf-8') as f:
            return f.read()
    except Exception as e:
        return f"Error reading log file: {e}"

def get_task_log_file_path(task_id):
    """Get the log file path for a specific task"""
    task = get_task(task_id)
    if not task:
        return None
    return task.log_file

def cleanup_old_tasks(max_tasks=100):
    """Clean up old completed/error tasks to prevent memory bloat"""
    if len(tasks) <= max_tasks:
        return
    
    # Sort tasks by start time (oldest first)
    sorted_tasks = sorted(tasks.items(), key=lambda x: x[1].start_time or 0)
    
    # Remove oldest completed/error tasks
    for task_id, task in sorted_tasks:
        if task.status in [TASK_STATUS_COMPLETED, TASK_STATUS_ERROR, TASK_STATUS_STOPPED] and len(tasks) > max_tasks:
            # Remove log file
            try:
                if os.path.exists(task.log_file):
                    os.remove(task.log_file)
            except Exception as e:
                print(f"Error removing log file {task.log_file}: {e}")
            
            # Remove from tasks dict
            del tasks[task_id]

def cleanup_temp_files():
    """Clean up any remaining .temp files from failed downloads"""
    try:
        import glob
        temp_files = []
        
        # Find all .temp files in the var/temp/medias directory
        temp_medias_dir = os.path.join('var', 'temp', 'medias')
        if os.path.exists(temp_medias_dir):
            for file in os.listdir(temp_medias_dir):
                if '.temp' in file:  # Handle both .temp and .temp.{extension} formats
                    temp_files.append(os.path.join(temp_medias_dir, file))
        

        
        if temp_files:
            print(f"🧹 Found {len(temp_files)} temporary files to clean up")
            for temp_file in temp_files:
                try:
                    os.remove(temp_file)
                    print(f"🗑️ Cleaned up: {temp_file}")
                except Exception as e:
                    print(f"⚠️ Failed to clean up {temp_file}: {e}")
            print(f"✅ Cleanup completed: {len(temp_files)} files removed")
        else:
            print("✅ No temporary files found")
            
    except Exception as e:
        print(f"❌ Error during temp file cleanup: {e}")

def cleanup_old_backups(file_path, max_backups=10):
    """Clean up old backup files, keeping only the last max_backups files"""
    try:
        if not os.path.exists(file_path):
            return
        
        # Get directory and base filename
        directory = os.path.dirname(file_path)
        base_filename = os.path.basename(file_path)
        
        # Find all backup files for this gamelist
        backup_files = []
        for filename in os.listdir(directory):
            if filename.startswith(base_filename + '.backup.'):
                backup_path = os.path.join(directory, filename)
                if os.path.isfile(backup_path):
                    # Get file modification time for sorting
                    mtime = os.path.getmtime(backup_path)
                    backup_files.append((mtime, backup_path))
        
        # Sort by modification time (oldest first)
        backup_files.sort(key=lambda x: x[0])
        
        # Remove old backups if we have more than max_backups
        if len(backup_files) > max_backups:
            files_to_remove = backup_files[:-max_backups]  # Keep the last max_backups files
            for _, backup_path in files_to_remove:
                try:
                    os.remove(backup_path)
                    print(f"🗑️ Removed old backup: {os.path.basename(backup_path)}")
                except Exception as e:
                    print(f"❌ Error removing old backup {backup_path}: {e}")
            
            print(f"✅ Cleaned up {len(files_to_remove)} old backup files, kept {max_backups} most recent")
        
    except Exception as e:
        print(f"❌ Error during backup cleanup for {file_path}: {e}")

def create_media_filename(rompath_or_romfile, media_extension):
    """
    Create media filename from ROM path or ROM filename, handling dots in ROM names correctly.
    Uses os.path.splitext to remove the file extension, preserving dots in the middle.
    Can accept either a full ROM path (e.g., './system/game.nes') or just a ROM filename (e.g., 'game.nes').
    """
    if not rompath_or_romfile:
        return f"unknown{media_extension}"
    
    # Extract filename without extension from path or filename
    rom_filename = os.path.splitext(os.path.basename(rompath_or_romfile))[0]
    
    # Add the media extension
    return f"{rom_filename}{media_extension}"

def is_task_running():
    """Check if any task is currently running"""
    global current_task_id
    if current_task_id and current_task_id in tasks:
        return tasks[current_task_id].status == TASK_STATUS_RUNNING
    return False

def can_start_task(task_type):
    """Check if a new task can be started"""
    if is_task_running():
        current_task_type = tasks[current_task_id].type if current_task_id else 'unknown'
        return False, f"Another task ({current_task_type}) is already running"
    return True, None

def queue_task(task_type, task_data=None):
    """Add a task to the queue if it can't start immediately"""
    if can_start_task(task_type)[0]:
        return True, "Task can start immediately"
    
    # Create a queued task
    task = create_task(task_type, task_data)
    task.status = TASK_STATUS_QUEUED
    
    # Add to queue
    task_info = {
        'task_id': task.id,
        'type': task_type,
        'data': task_data,
        'timestamp': time.time()
    }
    task_queue.append(task_info)
    return False, f"Task queued. Position: {len(task_queue)}"

def get_queue_status():
    """Get current queue status"""
    global current_task_id
    current_task = tasks.get(current_task_id) if current_task_id else None
    
    return {
        'current_task': current_task.to_dict_lightweight() if current_task else None,
        'queue_length': len(task_queue),
        'queued_tasks': task_queue
    }

def update_task_progress(message, progress_percentage=None, current_step=None, total_steps=None):
    """Update the current task progress and keep it synchronized"""
    global current_task_id
    if current_task_id and current_task_id in tasks:
        task = tasks[current_task_id]
        if task.status == TASK_STATUS_RUNNING:
            task.update_progress(message, progress_percentage, current_step, total_steps)
            # Add console logging for debugging
            print(f"DEBUG: {message}")

def update_task_stats():
    """Update the current task stats to keep them synchronized"""
    global current_task_id, scraping_stats
    if current_task_id and current_task_id in tasks:
        task = tasks[current_task_id]
        if task.status == TASK_STATUS_RUNNING:
            task.update_stats(scraping_stats.copy())



def cleanup_stuck_tasks():
    """Clean up tasks that are stuck in idle status for too long"""
    global tasks, current_task_id
    
    current_time = time.time()
    stuck_tasks = []
    
    for task_id, task in list(tasks.items()):
        # If task has been idle for more than 5 minutes, mark it as completed
        if (task.status == TASK_STATUS_IDLE and 
            task.start_time and 
            current_time - task.start_time > 300):  # 5 minutes
            
            print(f"Cleaning up stuck idle task: {task_id} (type: {task.type})")
            task.complete(success=False, error_message="Task stuck in idle state - cleaned up")
            stuck_tasks.append(task_id)
    
    if stuck_tasks:
        print(f"Cleaned up {len(stuck_tasks)} stuck tasks")
    
    return stuck_tasks

def add_task_to_queue(task_type, task_data, username=None):
    """Add a task to the queue for later processing"""
    global task_queue
    
    # Create a queued task with specific username if provided
    if username:
        task = Task(task_type, task_data, username)
        tasks[task.id] = task
    else:
        task = create_task(task_type, task_data)
    task.status = TASK_STATUS_QUEUED
    
    # Add to queue
    task_info = {
        'task_id': task.id,
        'type': task_type,
        'data': task_data,
        'timestamp': time.time()
    }
    task_queue.append(task_info)
    print(f"DEBUG: Added {task_type} task to queue. Position: {len(task_queue)}")
    
    # Only process if no task is currently running
    if not is_task_running():
        print(f"DEBUG: No task running, processing next queued task")
        process_next_queued_task()
    else:
        print(f"DEBUG: Task already running, queued task will wait")
    
    return task

def process_next_queued_task():
    """Process the next task in the queue"""
    global current_task_id, task_queue
    
    # Clean up any stuck tasks first
    cleanup_stuck_tasks()
    
    # Don't start a new task if one is already running
    if is_task_running():
        print(f"DEBUG: Task already running, not starting next queued task")
        return
    
    if not task_queue:
        print(f"DEBUG: No tasks in queue")
        return
    
    next_task = task_queue.pop(0)
    task_type = next_task['type']
    task_data = next_task.get('data', {})
    
    print(f"DEBUG: Processing next queued task: {task_type}")
    
    # Start the next task based on its type
    if task_type == 'media_scan':
        # Start media scan task
        system_name = task_data.get('system_name')
        if system_name:
            # Use the existing queued task instead of creating a new one
            task_id = next_task.get('task_id')
            if task_id and task_id in tasks:
                task = tasks[task_id]
                current_task_id = task.id
                task.start()
            else:
                # Fallback: create new task if existing one not found
                task = create_task('media_scan', task_data)
                current_task_id = task.id
                task.start()
            # Start media scan in background thread
            thread = threading.Thread(target=run_media_scan_task, args=(system_name,))
