def load_metadata_cache():
    """Load and cache all metadata from Metadata.xml for faster lookups"""
    global global_metadata_cache, global_metadata_cache_loaded, _launchbox_platforms_cache
    
    if global_metadata_cache_loaded:
        # Return a derived view for any legacy callers
        return {
            'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
            'games_cache': {k: {key: val for key, val in v.items() if key != 'images' and key != 'alternate_names'} for k, v in global_metadata_cache.items()},
            'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
        }
    
    try:
        # Check if cache file exists first
        cache_file = os.path.join('var', 'cache', 'launchbox_global_metadata_cache.pkl')
        if os.path.exists(cache_file):
            print("🔄 Loading LaunchBox metadata cache from file...")
            start_time = time.time()
            
            import pickle
            with open(cache_file, 'rb') as f:
                global_metadata_cache = pickle.load(f)
            
            global_metadata_cache_loaded = True
            
            # Generate LaunchBox platforms cache from flattened cache
            platforms = set()
            for game_id, game_data in global_metadata_cache.items():
                # With flattened structure, platform is directly in game_data
                platform = game_data.get('Platform', 'Unknown')
                if platform and platform.strip():
                    platforms.add(platform.strip())
            
            _launchbox_platforms_cache = sorted(list(platforms))
            
            
            end_time = time.time()
            print(f"✅ LaunchBox metadata cache loaded successfully in {end_time - start_time:.2f} seconds!")
            print(f"📊 Processed {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
            print(f"📊 Found {sum(len(v.get('images', [])) for v in global_metadata_cache.values())} total GameImage files across {len(global_metadata_cache)} games")
            print(f"📊 Cached {len(global_metadata_cache)} total games")
            print(f"📊 Cached {sum(len(v.get('alternate_names', [])) for v in global_metadata_cache.values())} games with alternate names")
            
            
            return {
                'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
                'games_cache': {k: {key: val for key, val in v.items() if key != 'images' and key != 'alternate_names'} for k, v in global_metadata_cache.items()},
                'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
            }
        
        print("🔄 Loading LaunchBox metadata cache from Metadata.xml...")
        start_time = time.time()
        
        # Ensure the directory exists before checking for the file
        metadata_path = get_launchbox_metadata_path()
        os.makedirs(os.path.dirname(metadata_path), exist_ok=True)
        
        if not os.path.exists(metadata_path):
            print(f"DEBUG: Metadata.xml not found at {metadata_path}")
            global_metadata_cache = {}
            global_metadata_cache_loaded = True
            return {
                'gameimage_cache': {},
                'games_cache': {},
                'alternate_names_cache': {}
            }
        
        # Parse the Metadata.xml using streaming parser for memory efficiency
        import xml.etree.ElementTree as ET
        consolidated = {}
        
        # Use iterparse for memory-efficient XML processing
        context = ET.iterparse(metadata_path, events=('start', 'end'))
        context = iter(context)
        event, root = next(context)
        
        game_images_count = 0
        games_count = 0
        alternate_names_count = 0
        
        for event, elem in context:
            if event == 'end':
                if elem.tag == 'GameImage':
                    game_images_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        image_data = {}
                        for child in elem:
                            if child.text:
                                image_data[child.tag] = child.text.strip()
                        entry['images'].append(image_data)
                    elem.clear()
                    
                elif elem.tag == 'Game':
                    games_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        game_data = {}
                        for child in elem:
                            if child.text:
                                game_data[child.tag] = child.text.strip()
                        entry['game'] = game_data
                    elem.clear()
                    
                elif elem.tag == 'GameAlternateName':
                    alternate_names_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        alt_name_data = {}
                        for child in elem:
                            if child.text:
                                alt_name_data[child.tag] = child.text.strip()
                        entry['alternate_names'].append(alt_name_data)
                    elem.clear()
        
        print(f"DEBUG: Found {game_images_count} GameImage entries in Metadata.xml")
        print(f"DEBUG: Found {games_count} Game entries in Metadata.xml")
        print(f"DEBUG: Found {alternate_names_count} GameAlternateName entries in Metadata.xml")
        
        # Transform consolidated cache to the new flattened structure
        flattened_cache = {}
        for db_id, entry in consolidated.items():
            game_data = entry.get('game', {})
            images = entry.get('images', [])
            alternate_names_data = entry.get('alternate_names', [])
            
            # Create flattened entry
            flattened_entry = {
                'Name': game_data.get('Name', ''),
                'Platform': game_data.get('Platform', ''),
                'DatabaseID': db_id,
                'images': images,
                'alternate_names': []
            }
            
            # Add other game fields
            for key, value in game_data.items():
                if key not in ['Name', 'Platform', 'DatabaseID']:
                    flattened_entry[key] = value
            
            # Process alternate names - extract just the name strings
            for alt_name_data in alternate_names_data:
                if isinstance(alt_name_data, dict):
                    alt_name = alt_name_data.get('AlternateName') or alt_name_data.get('Name')
                    if alt_name:
                        flattened_entry['alternate_names'].append(alt_name)
            
            flattened_cache[db_id] = flattened_entry
        
        # Update global consolidated cache (make a copy to avoid clearing it later)
        global_metadata_cache = flattened_cache.copy()
        global_metadata_cache_loaded = True
        
        # Save cache to file for worker processes to use
        _save_global_cache_to_file(flattened_cache)
        print(f"✅ Saved LaunchBox global metadata cache to var/cache/launchbox_global_metadata_cache.pkl")
        
        # Generate LaunchBox platforms cache from flattened cache (which has correct structure)
        platforms = set()
        for entry in flattened_cache.values():
            # With flattened structure, Platform is directly in entry
            platform = entry.get('Platform')
            if platform and platform.strip():
                platforms.add(platform.strip())
        
        _launchbox_platforms_cache = sorted(list(platforms))
        print(f"DEBUG: Cached {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
        
        
        load_time = time.time() - start_time
        
        # Count total images across all games before clearing memory
        total_images = sum(len(entry.get('images', [])) for entry in consolidated.values())
        
        print(f"✅ LaunchBox metadata cache loaded successfully in {load_time:.2f} seconds!")
        print(f"📊 Processed {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
        print(f"📊 Found {total_images} total GameImage files across {len(consolidated)} games")
        print(f"📊 Cached {len(consolidated)} total games")
        print(f"DEBUG: Cached {sum(1 for e in consolidated.values() if e.get('alternate_names'))} games with alternate names")
        
        # Clear large data structures from memory after cache generation
        print("🧹 Clearing large data structures from memory...")
        consolidated.clear()
        del consolidated
        
        
        return {
            'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
            'games_cache': {k: {key: val for key, val in v.items() if key != 'images' and key != 'alternate_names'} for k, v in global_metadata_cache.items()},
            'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
        }
        
    except Exception as e:
        print(f"ERROR: Failed to load metadata cache: {e}")
        import traceback
        traceback.print_exc()
        global_metadata_cache = {}
        global_metadata_cache_loaded = True
        return {
            'gameimage_cache': {},
            'games_cache': {},
            'alternate_names_cache': {}
        }

def get_cached_game_data(database_id):
    """Get cached game data including alternate names"""
    if not global_metadata_cache_loaded:
        load_metadata_cache()
    
    entry = global_metadata_cache.get(database_id) or {}
    # Return the entry directly since it's now flattened
    return entry

def get_cached_games_by_platform(platform):
    """Get all cached games for a specific platform"""
    if not global_metadata_cache_loaded:
        load_metadata_cache()
    
    platform_games = []
    for db_id, entry in global_metadata_cache.items():
        # With flattened structure, game data is directly in entry
        game_platform = entry.get('Platform')
        if game_platform == platform:
            platform_games.append(entry)
    
    return platform_games


def get_cache_statistics():
    """Get statistics about the current metadata cache"""
    if not global_metadata_cache_loaded:
        return {
            'status': 'not_loaded',
            'total_games': 0,
            'memory_usage_mb': 0
        }
    
    # Calculate memory usage of the global cache
    import sys
    memory_usage_bytes = sys.getsizeof(global_metadata_cache)
    # Add memory usage of all values in the cache
    for entry in global_metadata_cache.values():
        memory_usage_bytes += sys.getsizeof(entry)
        if isinstance(entry, dict):
            for key, value in entry.items():
                memory_usage_bytes += sys.getsizeof(key) + sys.getsizeof(value)
    
    memory_usage_mb = round(memory_usage_bytes / (1024 * 1024), 2)
    
    return {
        'status': 'loaded',
        'total_games': len(global_metadata_cache),
        'memory_usage_mb': memory_usage_mb
    }
def count_all_games_batch(systems_list):
    """Count games for all systems at once using fast XML parsing with iterparse.
    
    This uses lxml.etree.iterparse for memory-efficient streaming XML parsing,
    which is faster and more reliable than grep-based string matching.
    """
    system_counts = {}
    
    try:
        # Process each system's gamelist.xml file using fast XML parsing
        for system_name in systems_list:
            gamelist_path = get_gamelist_path(system_name)
            
            if not os.path.exists(gamelist_path):
                system_counts[system_name] = 0
                continue
            
            try:
                # Use iterparse for fast, memory-efficient XML parsing
                game_count = 0
                hidden_count = 0
                
                # Parse XML using iterparse (streaming parser - very fast)
                context = ET.iterparse(gamelist_path, events=('start', 'end'))
                context = iter(context)
                event, root = next(context)
                
                for event, elem in context:
                    if event == 'start' and elem.tag == 'game':
                        game_count += 1
                    elif event == 'end' and elem.tag == 'game':
                        # Check if this game is hidden
                        hidden_elem = elem.find('hidden')
                        if hidden_elem is not None and hidden_elem.text and hidden_elem.text.strip().lower() == 'true':
                            hidden_count += 1
                        # Clear element to free memory during streaming
                        elem.clear()
                
                # Calculate visible games (total - hidden)
                visible_count = max(0, game_count - hidden_count)
                system_counts[system_name] = visible_count
                
            except ET.XMLSyntaxError as e:
                print(f"XML syntax error in {gamelist_path}: {e}")
                system_counts[system_name] = 0
            except Exception as e:
                print(f"Error parsing {gamelist_path}: {e}")
                system_counts[system_name] = 0
    
    except Exception as e:
        print(f"Error in batch game counting: {e}")
        # Set all systems to 0 if batch processing fails
        for system_name in systems_list:
            if system_name not in system_counts:
                system_counts[system_name] = 0
    
    # Ensure all requested systems have counts (set to 0 if missing)
    for system_name in systems_list:
        if system_name not in system_counts:
            system_counts[system_name] = 0
    
    return system_counts

def parse_gamelist_xml(file_path):
    """Parse gamelist.xml file and return list of games"""
    try:
        # Check if file exists and is readable
        if not os.path.exists(file_path):
            print(f"Gamelist file does not exist: {file_path}")
            return []
        
        # Check file size
        file_size = os.path.getsize(file_path)
        if file_size == 0:
            print(f"Gamelist file is empty: {file_path}")
            return []
        
        # Try to read the file content first to check for corruption
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
                if not content.strip():
                    print(f"Gamelist file contains only whitespace: {file_path}")
                    return []
        except UnicodeDecodeError as e:
            print(f"Gamelist file has encoding issues: {file_path} - {e}")
            return []
        except Exception as e:
            print(f"Error reading gamelist file: {file_path} - {e}")
            return []
        
        # Parse XML
        tree = ET.parse(file_path)
        root = tree.getroot()
        
        # Check if root element is correct
        if root.tag != 'gameList':
            print(f"Invalid gamelist format: expected 'gameList' root, got '{root.tag}' in {file_path}")
            return []
        
        games = []
        
        for game in root.findall('game'):
            game_data = {}
            
            # Parse each field
            for field in game:
                tag = field.tag
                raw_text = field.text.strip() if field.text else ''
                # Fix over-escaped entities and decode to get original text for storage
                text = fix_over_escaped_xml_entities(raw_text) if raw_text else ''
                
                if tag == 'id':
                    game_data['id'] = int(text) if text.isdigit() else None
                elif tag == 'path':
                    game_data['path'] = text
                elif tag == 'name':
                    game_data['name'] = text
                elif tag == 'desc':
                    game_data['desc'] = text
                elif tag == 'genre':
                    game_data['genre'] = text
                elif tag == 'developer':
                    game_data['developer'] = text
                elif tag == 'publisher':
                    game_data['publisher'] = text
                elif tag == 'family':
                    game_data['family'] = text
                elif tag == 'rating':
                    game_data['rating'] = text
                elif tag == 'players':
                    game_data['players'] = text
                elif tag == 'image':
                    game_data['image'] = text
                elif tag == 'video':
                    game_data['video'] = text
                elif tag == 'marquee':
                    game_data['marquee'] = text
                elif tag == 'wheel':
                    game_data['wheel'] = text
                elif tag == 'boxart':
                    game_data['boxart'] = text
                elif tag == 'thumbnail':
                    game_data['thumbnail'] = text
                elif tag == 'screenshot':
                    game_data['screenshot'] = text
                elif tag == 'cartridge':
                    game_data['cartridge'] = text
                elif tag == 'fanart':
                    game_data['fanart'] = text
                elif tag == 'titleshot':
                    game_data['titleshot'] = text
                elif tag == 'manual':
                    game_data['manual'] = text
                elif tag == 'boxback':
                    game_data['boxback'] = text
                elif tag == 'extra1':
                    game_data['extra1'] = text
                elif tag == 'launchboxid':
                    game_data['launchboxid'] = int(text) if text.isdigit() else None
                elif tag == 'igdbid':
                    game_data['igdbid'] = int(text) if text.isdigit() else None
                elif tag == 'screenscraperid':
                    game_data['screenscraperid'] = int(text) if text.isdigit() else None
                elif tag == 'mobygamesid':
                    game_data['mobygamesid'] = text
                elif tag == 'customid':
                    game_data['customid'] = text
                elif tag == 'nbvotes':
                    game_data['nbvotes'] = int(text) if text.isdigit() else None
                elif tag == 'steamid':
                    game_data['steamid'] = int(text) if text.isdigit() else None
                elif tag == 'steamgridid':
                    game_data['steamgridid'] = int(text) if text.isdigit() else None
                elif tag == 'youtubeurl':
                    game_data['youtubeurl'] = text
                elif tag == 'hidden':
                    game_data['hidden'] = text
                elif tag == 'favorite':
                    # Handle boolean field - convert string to boolean
                    game_data['favorite'] = text.lower() == 'true' if text else False
                elif tag == 'kidgame':
                    # Handle boolean field - convert string to boolean
                    game_data['kidgame'] = text.lower() == 'true' if text else False
                else:
                    # Handle unknown tags by storing them as text
                    game_data[tag] = text
            
            # Ensure required fields exist
            if 'id' not in game_data:
                game_data['id'] = len(games) + 1
            if 'name' not in game_data:
                game_data['name'] = 'Unknown Game'
            if 'path' not in game_data:
                game_data['path'] = './unknown.zip'
            if 'desc' not in game_data:
                game_data['desc'] = ''
            # Initialize customid to empty string if not present (for grid display)
            if 'customid' not in game_data:
                game_data['customid'] = ''
            
            games.append(game_data)
        
        print(f"Successfully parsed {len(games)} games from {file_path}")
        return games
        
    except ET.ParseError as e:
        print(f"XML parsing error in gamelist.xml: {e}")
        print(f"File: {file_path}")
        print(f"File size: {os.path.getsize(file_path) if os.path.exists(file_path) else 'N/A'} bytes")
        
        # Try to create a backup of the corrupted file
        try:
            backup_path = f"{file_path}.corrupted.{int(time.time())}"
            import shutil
            shutil.copy2(file_path, backup_path)
            print(f"Created backup of corrupted file: {backup_path}")
        except Exception as backup_error:
            print(f"Failed to create backup: {backup_error}")
        
        return []
    except Exception as e:
        print(f"Unexpected error parsing gamelist.xml: {e}")
        print(f"File: {file_path}")
        return []

