@app.route('/api/steam-mappings', methods=['GET', 'PUT', 'POST'])
@login_required
def manage_steam_mappings():
    """Manage Steam image type mappings"""
    try:
        if request.method == 'GET':
            # Return current mappings and available media fields
            steam_mappings = scrappers_config.get('steam', {}).get('image_type_mappings', {})
            media_fields = config.get('media_fields', {})
            
            # Load Steam media types from static file
            steam_media_types = []
            try:
                with open('var/db/steam/mediastype.txt', 'r') as f:
                    steam_media_types = [line.strip() for line in f.readlines() if line.strip()]
            except FileNotFoundError:
                # Fallback to default values if file doesn't exist
                steam_media_types = ['capsule', 'logo', 'hero', 'screenshot']
            
            return jsonify({
                'success': True, 
                'steam_mappings': steam_mappings,
                'media_fields': media_fields,
                'steam_media_types': steam_media_types
            })
        
        elif request.method == 'PUT':
            # Update existing mapping
            data = request.get_json()
            if not data or 'steam_type' not in data or 'media_field' not in data:
                return jsonify({'error': 'Steam type and media field are required'}), 400
            
            steam_type = data['steam_type']
            media_field = data['media_field']
            
            # Validate that the media field exists
            if media_field not in config.get('media_fields', {}):
                return jsonify({'error': 'Invalid media field'}), 400
            
            # Update the mapping (media_field -> steam_type)
            if 'steam' not in scrappers_config:
                scrappers_config['steam'] = {}
            if 'image_type_mappings' not in scrappers_config['steam']:
                scrappers_config['steam']['image_type_mappings'] = {}
            
            # Update the mapping directly
            if steam_type:
                scrappers_config['steam']['image_type_mappings'][media_field] = steam_type
            else:
                # Remove mapping if empty
                scrappers_config['steam']['image_type_mappings'].pop(media_field, None)
            
            # Save to file
            with open('var/config/scrappers.json', 'w') as f:
                json.dump(scrappers_config, f, indent=4)
            
            return jsonify({'success': True, 'message': 'Steam mapping updated successfully'})
        
        elif request.method == 'POST':
            # Reset mapping to default
            data = request.get_json()
            if not data or 'media_field' not in data or not data.get('reset'):
                return jsonify({'error': 'Reset operation requires media_field and reset flag'}), 400
            
            media_field = data['media_field']
            
            # Define default mappings (media_field -> steam_type)
            default_mappings = {
                "boxart": "capsule",
                "marquee": "logo",
                "fanart": "hero",
                "image": "screenshot"
            }
            
            # Reset to default value
            if 'steam' not in scrappers_config:
                scrappers_config['steam'] = {}
            if 'image_type_mappings' not in scrappers_config['steam']:
                scrappers_config['steam']['image_type_mappings'] = {}
            
            # Add default mapping if it exists
            default_steam_type = default_mappings.get(media_field)
            if default_steam_type:
                scrappers_config['steam']['image_type_mappings'][media_field] = default_steam_type
            
            # Save to file
            with open('var/config/scrappers.json', 'w') as f:
                json.dump(scrappers_config, f, indent=4)
            
            return jsonify({'success': True, 'message': 'Steam mapping reset to default'})
    
    except Exception as e:
        return jsonify({'error': f'Failed to manage Steam mappings: {str(e)}'}), 500

# Cache for LaunchBox platforms (generated at startup)
_launchbox_platforms_cache = None

@app.route('/api/launchbox-platforms', methods=['GET'])
@login_required
def get_launchbox_platforms():
    """Get list of LaunchBox platforms from pre-generated cache"""
    global _launchbox_platforms_cache
    
    try:
        # Check if cache exists (should be generated at startup)
        if _launchbox_platforms_cache is not None:
            return jsonify({'success': True, 'platforms': _launchbox_platforms_cache})
        
        # If cache doesn't exist, try to load metadata cache which will generate it
        if not global_metadata_cache_loaded:
            load_metadata_cache()
        
        # Return the cache if it was generated
        if _launchbox_platforms_cache is not None:
            return jsonify({'success': True, 'platforms': _launchbox_platforms_cache})
        
        # Fallback: return empty list if metadata.xml is not available
        return jsonify({'success': True, 'platforms': []})
    
    except Exception as e:
        return jsonify({'error': f'Failed to load LaunchBox platforms: {str(e)}'}), 500

def clear_launchbox_platforms_cache():
    """Clear the LaunchBox platforms cache"""
    global _launchbox_platforms_cache
    _launchbox_platforms_cache = None

def flush_launchbox_caches():
    """Flush all LaunchBox-related caches in memory and files"""
    import os
    import shutil
    
    print("🧹 Flushing all LaunchBox-related caches...")
    
    # Clear in-memory caches
    global global_metadata_cache_loaded, global_metadata_cache, _launchbox_platforms_cache, global_launchbox_indexes_loaded, global_launchbox_partition_index
    global_metadata_cache_loaded = False
    global_metadata_cache = {}
    _launchbox_platforms_cache = None
    global_launchbox_indexes_loaded = False
    global_launchbox_partition_index = None
    
    # Note: MobyGames partitioned index cache is not related to LaunchBox and should not be removed
    
    # Clear LaunchBox global metadata cache
    try:
        global_cache_file = os.path.join('var', 'cache', 'launchbox_global_metadata_cache.pkl')
        if os.path.exists(global_cache_file):
            os.remove(global_cache_file)
            print("✅ Removed LaunchBox global metadata cache")
    except Exception as e:
        print(f"⚠️ Warning: Could not remove LaunchBox global cache: {e}")
    
    # Clear all platform-specific caches
    try:
        cache_dir = os.path.join('var', 'cache')
        if os.path.exists(cache_dir):
            for filename in os.listdir(cache_dir):
                if filename.startswith('launchbox_platform_') and filename.endswith('_cache.pkl'):
                    file_path = os.path.join(cache_dir, filename)
                    os.remove(file_path)
                    print(f"✅ Removed platform cache: {filename}")
    except Exception as e:
        print(f"⚠️ Warning: Could not remove platform caches: {e}")
    
    # Clear any other LaunchBox-related cache files
    try:
        cache_dir = os.path.join('var', 'cache')
        if os.path.exists(cache_dir):
            for filename in os.listdir(cache_dir):
                if 'launchbox' in filename.lower() and filename.endswith('.pkl'):
                    file_path = os.path.join(cache_dir, filename)
                    os.remove(file_path)
                    print(f"✅ Removed LaunchBox cache: {filename}")
    except Exception as e:
        print(f"⚠️ Warning: Could not remove additional LaunchBox caches: {e}")
    
    print("✅ All LaunchBox-related caches flushed successfully")

@app.route('/api/rom-system/<system_name>/gamelist/batch', methods=['PUT'])
@login_required
def rom_system_gamelist_batch(system_name):
    """Batch update multiple games in gamelist for a specific ROM system"""
    try:
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Get gamelist path from var/gamelists
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        data = request.get_json()
        if not data or 'games' not in data:
            return jsonify({'error': 'Invalid request data: must provide games array'}), 400
        
        updated_games = data['games']
        if not isinstance(updated_games, list) or len(updated_games) == 0:
            return jsonify({'error': 'Invalid request data: games must be a non-empty array'}), 400
        
        # Load existing gamelist
        games = parse_gamelist_xml(gamelist_path)
        
        # Create a map of rom_path -> updated_game for quick lookup
        updated_games_map = {game.get('path'): game for game in updated_games}
        
        # Update all games in the gamelist
        updated_count = 0
        updated_paths = []
        for i, game in enumerate(games):
            rom_path = game.get('path')
            if rom_path in updated_games_map:
                # Update the game in place
                games[i].update(updated_games_map[rom_path])
                updated_count += 1
                updated_paths.append(rom_path)
        
        if updated_count == 0:
            return jsonify({'error': 'No games found to update'}), 404
        
        # Write updated gamelist once
        write_gamelist_xml(games, gamelist_path)
        
        # Notify about the batch update
        notify_gamelist_updated(system_name, len(games), updated_count=updated_count)
        
        return jsonify({
            'success': True,
            'message': f'Successfully updated {updated_count} game(s)',
            'count': len(games),
            'updated_count': updated_count
        })
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'error': f'Error updating gamelist: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/gamelist', methods=['GET', 'PUT'])
@login_required
def rom_system_gamelist(system_name):
    """Get or update gamelist for a specific ROM system"""
    try:
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Get gamelist path from var/gamelists
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            # Return empty games array instead of 404 for systems without gamelist
            return jsonify({
                'success': True,
                'system': system_name,
                'games': [],
                'count': 0
            })
        
        if request.method == 'GET':
            # Parse the actual gamelist.xml file
            games = parse_gamelist_xml(gamelist_path)
            

            
            # Sort games by name for consistent ordering
            games.sort(key=lambda x: x.get('name', '').lower())
            
            return jsonify({
                'success': True,
                'system': system_name,
                'games': games,
                'count': len(games)
            })
        elif request.method == 'PUT':
            # Update the gamelist.xml file
            data = request.get_json()
            if not data:
                return jsonify({'error': 'Invalid request data'}), 400
            
            # Check if this is a single game update (optimized path)
            if 'rom_path' in data and 'game' in data:
                # Optimized single game update using rom_path as key
                rom_path = data['rom_path']
                updated_game = data['game']
                
                # Load existing gamelist
                games = parse_gamelist_xml(gamelist_path)
                
                # Find and update the game by rom_path
                game_found = False
                for i, game in enumerate(games):
                    if game.get('path') == rom_path:
                        # Update the game in place
                        games[i].update(updated_game)
                        game_found = True
                        break
                
                if not game_found:
                    return jsonify({'error': f'Game not found with ROM path: {rom_path}'}), 404
                
                # Write updated gamelist
                write_gamelist_xml(games, gamelist_path)
                
                # Notify about the single game update
                notify_gamelist_updated(system_name, len(games))
                notify_game_updated(system_name, rom_path, list(updated_game.keys()))
                
                return jsonify({
                    'success': True,
                    'message': f'Successfully updated game: {rom_path}',
                    'count': len(games)
                })
            
            # Legacy full gamelist update path
            if 'games' not in data:
                return jsonify({'error': 'Invalid request data: must provide either single game (rom_path + game) or full games array'}), 400
            
            print(f"🔔 PUT request received for system: {system_name}")
            
            games = data['games']
            delete_rom_paths = data.get('delete_rom_paths', [])
            
            def normalize_gamelist_path(path_value):
                if not path_value:
                    return None
                normalized = path_value.replace('\\', '/').strip()
                while normalized.startswith('./'):
                    normalized = normalized[2:]
                normalized = normalized.lstrip('/')
                if normalized.lower().startswith('roms/'):
                    normalized = normalized[5:]
                if not normalized.lower().startswith(system_name.lower() + '/'):
                    normalized = f"{system_name}/{normalized}"
                return os.path.normpath(normalized).replace('\\', '/')
            
            def resolve_media_path(value):
                if not value:
                    return None
                path = value.strip()
                if not path or path.lower().startswith('http://') or path.lower().startswith('https://'):
                    return None
                path = path.replace('\\', '/')
                while path.startswith('./'):
                    path = path[2:]
                path = path.lstrip('/')
                if path.lower().startswith('roms/'):
                    rel = path[5:]
                elif path.lower().startswith(system_name.lower() + '/'):
                    rel = path
                else:
                    rel = f"{system_name}/{path}"
                abs_path = os.path.abspath(os.path.join(ROMS_FOLDER, rel))
                return abs_path
            
            # Log the deletion operation
            if delete_rom_paths:
                app.logger.info(f'Deleting {len(delete_rom_paths)} games from {system_name} gamelist using ROM file paths')
                
                # Delete associated files for each deleted game
                deleted_files = []
                failed_deletions = []
                media_fields = ['image', 'thumbnail', 'video', 'marquee', 'manual', 'boxart', 'boxback', 'boxside',
                                'cartridge', 'wheel', 'bezel', 'fanart', 'extra1', 'screenshot', 'titlescreen']
                
                # Load existing gamelist once to find original media references
                existing_games = parse_gamelist_xml(gamelist_path)
                existing_games_map = {}
                existing_games_basename_map = {}
                for existing_game in existing_games:
                    normalized_path = normalize_gamelist_path(existing_game.get('path'))
                    if not normalized_path:
                        continue
                    key = normalized_path.lower()
                    existing_games_map.setdefault(key, existing_game)
                    basename_key = os.path.basename(key)
                    existing_games_basename_map.setdefault(basename_key, existing_game)
                
                allowed_dirs = [
                    os.path.abspath(os.path.join(app.root_path, 'roms')),
                    os.path.abspath(os.path.join(app.root_path, 'media'))
                ]
                
                for rom_path in delete_rom_paths:
                    try:
                        # Convert relative path to absolute path relative to ROMS_FOLDER
                        if not os.path.isabs(rom_path):
                            rom_path = os.path.normpath(os.path.join(ROMS_FOLDER, rom_path))
                        
                        rom_abs_path = os.path.abspath(rom_path)
                        
                        is_allowed = False
                        for allowed_dir in allowed_dirs:
                            if rom_abs_path.startswith(allowed_dir):
                                is_allowed = True
                                break
                        
                        if not is_allowed:
                            failed_deletions.append({'path': rom_path, 'error': 'Access denied'})
                            continue
                        
                        # Delete ROM file
                        if os.path.exists(rom_abs_path):
                            os.remove(rom_abs_path)
                            deleted_files.append(f"ROM: {rom_path}")
                        else:
                            failed_deletions.append({'path': rom_path, 'error': 'ROM file not found'})
                        
                        rom_relative = os.path.relpath(rom_abs_path, ROMS_FOLDER).replace('\\', '/')
                        rom_key = rom_relative.lower()
                        basename_key = os.path.basename(rom_key)
                        game_entry = existing_games_map.get(rom_key) or existing_games_basename_map.get(basename_key)
                        
                        if game_entry:
                            for field in media_fields:
                                media_value = game_entry.get(field)
                                if not media_value:
                                    continue
                                media_abs_path = resolve_media_path(media_value)
                                if not media_abs_path:
                                    continue
                                if not any(media_abs_path.startswith(allowed_dir) for allowed_dir in allowed_dirs):
                                    continue
                                try:
                                    if os.path.exists(media_abs_path):
                                        os.remove(media_abs_path)
                                        deleted_files.append(f"{field}: {os.path.relpath(media_abs_path, system_path)}")
                                except Exception as e:
                                    failed_deletions.append({'path': media_abs_path, 'error': str(e)})
                        
                    except Exception as e:
                        failed_deletions.append({'path': rom_path, 'error': str(e)})
                        app.logger.error(f'Error deleting files for ROM {rom_path}: {e}')
                
                app.logger.info(f'File deletion completed: {len(deleted_files)} files deleted, {len(failed_deletions)} failed')
            
            # Write the updated games back to gamelist.xml
            write_gamelist_xml(games, gamelist_path)
            
            # Get changed games data before notifications
            changed_games = data.get('changed_games', [])
            print(f"🔔 Changed games data: {changed_games}")
            
            # Notify all connected clients about the gamelist update
            if delete_rom_paths:
                print(f"🔔 Notifying about gamelist update with deletions")
                notify_gamelist_updated(system_name, len(games), len(delete_rom_paths), len(changed_games))
                notify_game_deleted(system_name, deleted_files)
            else:
                print(f"🔔 Notifying about gamelist update without deletions")
                notify_gamelist_updated(system_name, len(games), 0, len(changed_games))
                
            # Notify about individual game changes if provided
            print(f"🔔 Processing {len(changed_games)} changed games for individual notifications")
            for changed_game in changed_games:
                if changed_game.get('changed_fields'):
                    print(f"🔔 Notifying about game update: {changed_game['game_name']} with fields: {changed_game['changed_fields']}")
                    notify_game_updated(system_name, changed_game.get('rom_path', ''), changed_game['changed_fields'])
                else:
                    print(f"⚠️  Changed game missing changed_fields: {changed_game}")
            
            return jsonify({
                'success': True,
                'message': f'Successfully saved {len(games)} games to {system_name}',
                'count': len(games),
                'deleted_count': len(delete_rom_paths),
                'deleted_files': deleted_files if delete_rom_paths else [],
                'failed_deletions': failed_deletions if delete_rom_paths else []
            })
            
    except Exception as e:
        return jsonify({'error': str(e)}), 500

