from game_utils import normalize_game_name

def normalize_igdb_url(image_id: str, media_type: str = 'default') -> str:
    """Normalize IGDB image URL - always use .png extension"""
    if not image_id:
        return ""
    
    # Use different templates for different media types
    if media_type == 'cover':
        template = 't_cover_big'
    elif media_type == 'artwork':
        template = 't_1080p'
    else:
        template = 't_720p'
    
    # Construct IGDB image URL using local image ID - always use .png
    return f"https://images.igdb.com/igdb/image/upload/{template}/{image_id}.png"

def get_top_matches(game_name, metadata_games, target_platform, top_n=20, mapping_config=None):
    """Get top N matches for a game name using global partitioned indexes and Jaro-Winkler similarity"""
    print(f"🔍 DEBUG: get_top_matches called for '{game_name}' (platform: {target_platform}, top_n: {top_n})")
    
    if not metadata_games:
        print(f"🔍 DEBUG: No metadata games provided, returning empty list")
        return []
    
    # Normalize search name without parentheses for better matching
    normalized_name = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=False)
    print(f"🔍 DEBUG: Normalized name (without parentheses): '{normalized_name}'")
    
    if not normalized_name:
        print(f"🔍 DEBUG: Normalized name is empty, returning empty list")
        return []
    
    matches = []
    
    # Use global partitioned indexes
    partition_index = load_launchbox_partitioned_indexes()
    if not partition_index or target_platform not in partition_index:
        print(f"🔍 DEBUG: Global partitioned indexes not available for platform '{target_platform}'")
        return []
    
    print(f"🔍 DEBUG: Using global partitioned indexes for platform '{target_platform}'")
    
    # Get the first character to search in the right partition
    first_char = normalized_name[0] if normalized_name else 'other'
    print(f"🔍 DEBUG: Searching in partition '{first_char}'")
    
    # Search through all games in the platform partition
    platform_partition = partition_index[target_platform]
    print(f"🔍 DEBUG: Platform partition has {len(platform_partition)} entries")
    
    for normalized_game_name_with_parens, launchboxid in platform_partition.items():
        # Index keys are already normalized, use them directly
        normalized_game_name = normalized_game_name_with_parens
        
        # Only search games that start with the same character (partition optimization)
        if normalized_game_name.startswith(first_char):
            # Calculate similarity using configured algorithm
            from game_utils import calculate_similarity
            similarity = calculate_similarity(normalized_name, normalized_game_name)
        
            # Only consider good matches
            if similarity >= 0.7:
                # Find the game in metadata_games
                for game in metadata_games:
                    if str(game.get('DatabaseID', '')) == str(launchboxid):
                        # Get box image URL for this game
                        database_id = game.get('DatabaseID', '')
                        box_image_url = get_launchbox_box_image_url(database_id) if database_id else None
                        
                        # Create match info
                        match_info = {
                            'game': game,
                            'score': similarity,
                            'match_type': 'main',
                            'matched_name': game.get('Name', ''),
                            'database_id': database_id,
                            'name': game.get('Name', ''),
                            'overview': game.get('Overview', ''),
                            'developer': game.get('Developer', ''),
                            'publisher': game.get('Publisher', ''),
                            'box_image_url': box_image_url
                        }
                        
                        # Add mapped fields dynamically based on mapping configuration
                        if mapping_config:
                            for launchbox_field, gamelist_field in mapping_config.items():
                                match_info[gamelist_field] = game.get(launchbox_field, '')
                        
                        matches.append(match_info)
                        print(f"🔍 DEBUG: Found match: '{game.get('Name', '')}' -> similarity: {similarity:.4f}")
                        break
    
    # Check if we already have a perfect match (100% similarity)
    has_perfect_match = False
    for match in matches:
        if match.get('score', 0) >= 1.0:
            has_perfect_match = True
            print(f"🔍 DEBUG: Found perfect match (100%), skipping first part search")
            break
    
    # If game name contains ":" or "-", do an extra search with the first part
    # But skip if we already have a perfect match
    if not has_perfect_match and (':' in game_name or '-' in game_name):
        import re
        # Split by ":" or "-" and get the first part
        first_part = re.split(r'[:\-]', game_name, 1)[0].strip()
        if first_part and first_part != game_name:
            print(f"🔍 DEBUG: Game name contains ':' or '-', doing extra search with first part: '{first_part}'")
            
            # Normalize the first part
            normalized_first_part = normalize_game_name(first_part, remove_paranthesis=True, remove_articles=False)
            print(f"🔍 DEBUG: Normalized first part: '{normalized_first_part}'")
            
            if normalized_first_part:
                # Get the first character for partition search
                first_char_first_part = normalized_first_part[0] if normalized_first_part else 'other'
                print(f"🔍 DEBUG: Searching first part in partition '{first_char_first_part}'")
                
                # Search through all games in the platform partition for the first part
                for normalized_game_name_with_parens, launchboxid in platform_partition.items():
                    # Normalize index entry name without parentheses for comparison
                    normalized_game_name = normalized_game_name_with_parens
                    
                    # Only search games that start with the same character (partition optimization)
                    if normalized_game_name.startswith(first_char_first_part):
                        # Calculate similarity using configured algorithm
                        # Compare normalized first part of source against full normalized database name
                        from game_utils import calculate_similarity
                        similarity = calculate_similarity(normalized_first_part, normalized_game_name)
                    
                        # Only consider good matches
                        if similarity >= 0.7:
                            # Find the game in metadata_games
                            for game in metadata_games:
                                if str(game.get('DatabaseID', '')) == str(launchboxid):
                                    # Get box image URL for this game
                                    database_id = game.get('DatabaseID', '')
                                    box_image_url = get_launchbox_box_image_url(database_id) if database_id else None
                                    
                                    # Create match info
                                    match_info = {
                                        'game': game,
                                        'score': similarity,
                                        'match_type': 'first_part',  # Mark as first part match
                                        'matched_name': game.get('Name', ''),
                                        'database_id': database_id,
                                        'name': game.get('Name', ''),
                                        'overview': game.get('Overview', ''),
                                        'developer': game.get('Developer', ''),
                                        'publisher': game.get('Publisher', ''),
                                        'box_image_url': box_image_url
                                    }
                                    
                                    # Add mapped fields dynamically based on mapping configuration
                                    if mapping_config:
                                        for launchbox_field, gamelist_field in mapping_config.items():
                                            match_info[gamelist_field] = game.get(launchbox_field, '')
                                    
                                    matches.append(match_info)
                                    print(f"🔍 DEBUG: Found first part match: '{game.get('Name', '')}' -> similarity: {similarity:.4f}")
                                    break
    
    print(f"🔍 DEBUG: Found {len(matches)} total matches before deduplication")
    
    # Deduplicate matches by DatabaseID, keeping the best score for each unique game
    seen_database_ids = {}
    deduplicated_matches = []
    
    for match in matches:
        database_id = match.get('database_id', '')
        if database_id and database_id in seen_database_ids:
            # Keep the match with the higher score
            existing_match = seen_database_ids[database_id]
            if match['score'] > existing_match['score']:
                # Replace the existing match with this better one
                deduplicated_matches.remove(existing_match)
                deduplicated_matches.append(match)
                seen_database_ids[database_id] = match
        elif database_id:
            # New unique game, add it
            deduplicated_matches.append(match)
            seen_database_ids[database_id] = match
        else:
            # No database_id, add it (shouldn't happen with LaunchBox data)
            deduplicated_matches.append(match)
    
    print(f"🔍 DEBUG: After deduplication: {len(deduplicated_matches)} unique matches")
    
    # Sort by score (highest first) and return top N
    deduplicated_matches.sort(key=lambda x: x['score'], reverse=True)
    result = deduplicated_matches[:top_n]
    print(f"🔍 DEBUG: Returning {len(result)} matches (requested: {top_n})")
    
    # Log the top matches for debugging
    for i, match in enumerate(result[:5]):  # Log top 5 matches
        print(f"🔍 DEBUG: Match {i+1}: '{match['matched_name']}' (score: {match['score']:.4f}, type: {match['match_type']}, ID: {match['database_id']})")
    
    return result

def _dedupe_games_by_path(games):
    """Return a new list with duplicates removed by 'path' (first occurrence wins)."""
    seen_paths = set()
    deduped = []
    for game in games:
        raw_path = (game.get('path') or '').strip()
        key = raw_path if raw_path else f"__no_path__::{(game.get('name') or '').strip().lower()}"
        if key in seen_paths:
            continue
        seen_paths.add(key)
        deduped.append(game)
    removed_count = max(0, len(games) - len(deduped))
    if removed_count:
        print(f"🧹 Deduped games by path: removed {removed_count} duplicate entries (kept first occurrence)")
    return deduped

def write_gamelist_xml(games, file_path):
    """Write games list to gamelist.xml file (deduped by path)."""
    try:
        games_to_write = _dedupe_games_by_path(games)
        root = ET.Element('gameList')
        
        for game in games_to_write:
            game_elem = ET.SubElement(root, 'game')
            
            # Add all game fields
            for field, value in game.items():
                # Format releasedate field to ISO 8601 format
                if field == 'releasedate' and value:
                    value = format_releasedate_to_iso8601(value)
                
                # Handle boolean fields - convert to lowercase string
                if field in ['favorite', 'kidgame']:
                    if value == 'true' or value is True:
                        value = 'true'
                    elif value == 'false' or value is False:
                        value = 'false'
                    else:
                        # Keep empty string as empty (don't convert to 'false')
                        value = ''
                
                # Add all fields from the game data
                field_elem = ET.SubElement(game_elem, field)
                field_elem.text = str(value) if value else ''
                
        
        # Write to file with formatting
        tree = ET.ElementTree(root)
        save_formatted_gamelist_xml(tree, file_path)
        
    except Exception as e:
        print(f"Error writing gamelist.xml: {e}")


@app.route('/api/scrap-launchbox/<system_name>', methods=['GET', 'POST'])
@login_required
def scrap_launchbox_simple(system_name):
    """Start simplified LaunchBox scraping process that runs in main thread using global cache"""
    try:
        if not system_name:
            return jsonify({'error': 'System name required'}), 400
        
        # Get parameters from POST body if available
        selected_games = None
        enable_partial_match_modal = False
        force_download = False
        selected_fields = None
        overwrite_text_fields = False
        
        if request.method == 'POST':
            try:
                data = request.get_json()
                if data:
                    selected_games = data.get('selected_games')
                    enable_partial_match_modal = data.get('enable_partial_match_modal', False)
                    force_download = data.get('force_download', False)
                    selected_fields = data.get('selected_fields')
                    overwrite_text_fields = data.get('overwrite_text_fields', False)
            except Exception as e:
                print(f"Error parsing POST data: {e}")
                return jsonify({'error': f'Invalid JSON data: {str(e)}'}), 400
        
        # Add task to queue instead of running directly
        task = add_task_to_queue('launchbox_scraping', {
            'system_name': system_name,
            'selected_games': selected_games,
            'enable_partial_match_modal': enable_partial_match_modal,
            'force_download': force_download,
            'selected_fields': selected_fields,
            'overwrite_text_fields': overwrite_text_fields
        })
        
        return jsonify({
            'success': True,
            'message': 'LaunchBox scraping task queued',
            'system': system_name,
            'task_id': task.id
        })
        
    except Exception as e:
        print(f"Error in scrap_launchbox_simple endpoint: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

