def run_async_safely(coro):
    """Safely run an async coroutine, handling event loop conflicts"""
    import time
    
    async_safely_start_time = time.time()
    
    try:
        # Try asyncio.run first (fastest option)
        result = asyncio.run(coro)
        async_safely_end_time = time.time()
        print(f"⏱️ run_async_safely (asyncio.run) took {async_safely_end_time - async_safely_start_time:.3f} seconds")
        return result
    except RuntimeError as e:
        if "cannot be called from a running event loop" in str(e):
            # We're in an async context, need to use thread
            print(f"🔧 DEBUG: Event loop conflict detected, using thread fallback")
            import concurrent.futures
            import threading
            
            def run_in_new_thread():
                """Run the coroutine in a completely new thread with its own event loop"""
                new_loop = asyncio.new_event_loop()
                asyncio.set_event_loop(new_loop)
                try:
                    return new_loop.run_until_complete(coro)
                finally:
                    new_loop.close()
            
            with concurrent.futures.ThreadPoolExecutor() as executor:
                future = executor.submit(run_in_new_thread)
                result = future.result()
                async_safely_end_time = time.time()
                print(f"⏱️ run_async_safely (thread fallback) took {async_safely_end_time - async_safely_start_time:.3f} seconds")
                return result
        else:
            # Other RuntimeError, re-raise
            raise e
    except Exception as e:
        print(f"🔧 DEBUG: run_async_safely error: {e}")
        raise e

def download_and_save_media(media_url, game, media_type, system_name):
    """Download and save media to the appropriate directory"""
    try:
        print(f"🔧 DEBUG: download_and_save_media called with URL: {media_url}, type: {media_type}, system: {system_name}")
        
        # Get media field configuration
        config_path = os.path.join('var', 'config', 'config.json')
        if not os.path.exists(config_path):
            print(f"🔧 DEBUG: Config file not found at {config_path}")
            return False
        
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        
        if 'media_fields' not in config:
            print(f"🔧 DEBUG: No media_fields in config")
            return False
            
        if media_type not in config['media_fields']:
            print(f"🔧 DEBUG: Media type '{media_type}' not found in config. Available types: {list(config['media_fields'].keys())}")
            return False
        
        media_config = config['media_fields'][media_type]
        target_dir = media_config.get('directory', f'media/{media_type}')
        # For manual/map/magazine types, determine extension from URL or default to .pdf
        if media_type == 'manual' or media_type == 'map' or media_type == 'magazine':
            # Check if URL indicates CBZ or PDF
            if media_url and (media_url.lower().endswith('.cbz') or '.cbz' in media_url.lower()):
                target_extension = '.cbz'
            else:
                target_extension = '.pdf'
        else:
            target_extension = media_config.get('target_extension', '.png')
        
        print(f"🔧 DEBUG: Media config - target_dir: {target_dir}, target_extension: {target_extension}")
        
        if not target_dir.startswith('media/'):
            target_dir = f'media/{target_dir}'
        
        # Create target directory
        full_target_dir = os.path.join('roms', system_name, target_dir)
        print(f"🔧 DEBUG: Creating target directory: {full_target_dir}")
        os.makedirs(full_target_dir, exist_ok=True)
        
        # Generate filename
        media_filename = create_media_filename(game.get('path', ''), target_extension)
        target_path = os.path.join(full_target_dir, media_filename)
        print(f"🔧 DEBUG: Target file path: {target_path}")
        
        # Download the media
        print(f"🔧 DEBUG: Downloading from URL: {media_url}")
        import requests
        response = requests.get(media_url, timeout=30)
        response.raise_for_status()
        print(f"🔧 DEBUG: Download successful, content length: {len(response.content)}")
        
        # Save the file
        with open(target_path, 'wb') as f:
            f.write(response.content)
        print(f"🔧 DEBUG: File saved to {target_path}")
        
        # For manual/map (PDF/CBZ) types, skip image processing - these files should not be converted/resized
        if media_type != 'manual' and media_type != 'map':
            # Convert and/or resize image in a single operation (optimized)
            from game_utils import should_process_field, convert_and_resize_image_replace
            print(f"🔧 DEBUG: Checking processing for media_type: {media_type}")
            print(f"🔧 DEBUG: Config media_fields: {config.get('media_fields', {}).get(media_type, 'NOT_FOUND')}")
            should_process, target_extension, target_width, target_height = should_process_field(media_type, config)
            print(f"🔧 DEBUG: should_process: {should_process}, target_extension: {target_extension}, target_width: {target_width}, target_height: {target_height}")
            
            if should_process:
                print(f"🔧 DEBUG: Processing media - convert: {bool(target_extension)}, resize: {target_width}x{target_height}")
                processed_path, process_status = convert_and_resize_image_replace(
                    target_path, target_extension, target_width, target_height
                )
                print(f"🔧 DEBUG: Processing result - status: {process_status}")
                if process_status in ["converted", "resized", "converted_and_resized"]:
                    target_path = processed_path
                    media_filename = os.path.basename(target_path)
                    print(f"🔧 DEBUG: Processed media: {process_status} - {media_filename}")
                elif process_status == "failed":
                    print(f"🔧 DEBUG: Failed to process media, keeping original: {media_filename}")
            else:
                print(f"🔧 DEBUG: No processing needed for field: {media_type}")
        else:
            print(f"🔧 DEBUG: Skipping image processing for PDF (manual) type")
        
        # Update game data
        relative_path = os.path.join('.', target_dir, media_filename)
        game[media_type] = relative_path
        print(f"🔧 DEBUG: Updated game[{media_type}] = {relative_path}")
        
        print(f"🔧 DEBUG: Downloaded media to {target_path}")
        return True
        
    except Exception as e:
        print(f"🔧 DEBUG: Error downloading media: {e}")
        import traceback
        print(f"🔧 DEBUG: Traceback: {traceback.format_exc()}")
        return False

@app.route('/api/find-best-matches-mobygames', methods=['POST'])
@login_required
def find_best_matches_mobygames_endpoint():
    """Find best matches for selected games using MobyGames database"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        system_name = data.get('system_name')
        selected_games = data.get('selected_games', [])
        
        if not system_name:
            return jsonify({'error': 'System name required'}), 400
        
        if not selected_games:
            return jsonify({'error': 'No games selected'}), 400
        
        # Get the global MobyGames service instance
        mobygames_service = load_mobygames_service()
        
        if not mobygames_service:
            return jsonify({'error': 'MobyGames service not available'}), 500
        
        # Load gamelist to get game details
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        all_games = parse_gamelist_xml(gamelist_path)
        if not all_games:
            return jsonify({'error': 'No games found in gamelist'}), 400
        
        # Find selected games in gamelist
        games_to_process = [g for g in all_games if g.get('path') in selected_games]
        
        if not games_to_process:
            return jsonify({'error': 'No selected games found in gamelist'}), 404
        
        results = []
        for game_data in games_to_process:
            game_name = game_data.get('name', '')
            if not game_name:
                continue
            
            # Search MobyGames for best matches
            # The search function will normalize internally using normalize_game_name
            matches = mobygames_service.search_games(system_name, game_name, limit=5)
            
            if matches:
                # Map MobyGames data structure to expected format
                mapped_matches = []
                for match in matches:
                    mapped_match = {
                        'name': match.get('title', ''),
                        'game_id': match.get('id', ''),
                        'similarity_score': match.get('score', 0),
                        'publisher': 'Unknown Publisher'
                    }
                    mapped_matches.append(mapped_match)
                
                # Sort matches to prioritize exact string matches for 100% similarity
                def sort_key(match):
                    score = match.get('similarity_score', 0)
                    name = match.get('name', '')
                    
                    # For 100% matches, prioritize exact string matches
                    if score >= 0.99:  # 99%+ similarity (essentially 100%)
                        if name.lower() == game_name.lower():
                            return (0, -score)  # Exact match first, then by score
                        else:
                            return (1, -score)  # Non-exact match second, then by score
                    else:
                        return (2, -score)  # Non-100% matches last, by score
                
                mapped_matches.sort(key=sort_key)
                
                # Get the best match (first result after sorting)
                best_match = mapped_matches[0]
                
                results.append({
                    'game_path': game_data.get('path', ''),
                    'game_name': game_name,
                    'existing_mobygamesid': game_data.get('mobygamesid'),
                    'game_data': game_data,  # Include full game data for publisher info
                    'match_found': True,
                    'best_match': best_match,
                    'all_matches': mapped_matches
                })
            else:
                results.append({
                    'game_path': game_data.get('path', ''),
                    'game_name': game_name,
                    'existing_mobygamesid': game_data.get('mobygamesid'),
                    'match_found': False,
                    'best_match': None,
                    'all_matches': []
                })
        
        return jsonify({
            'success': True,
            'results': results,
            'total_games': len(games_to_process),
            'matched_games': len([r for r in results if r['match_found']])
        })
        
    except Exception as e:
        print(f"Error in find_best_matches_mobygames endpoint: {e}")
        return jsonify({'error': f'Failed to find MobyGames matches: {str(e)}'}), 500

