def get_launchbox_box_image_url(launchbox_id):
    """Get boxart image URL for a LaunchBox game using configuration mapping"""
    if not launchbox_id:
        print(f"🔍 DEBUG: get_launchbox_box_image_url called with empty launchbox_id")
        return None
    
    try:
        # Use the global metadata cache
        if not global_metadata_cache:
            print(f"🔍 DEBUG: Loading metadata cache for box image lookup")
            load_metadata_cache()
        
        game_metadata = global_metadata_cache.get(launchbox_id)
        if not game_metadata:
            print(f"🔍 DEBUG: No game metadata found for ID {launchbox_id}")
            return None
        
        print(f"🔍 DEBUG: Found game metadata for ID {launchbox_id}, checking for images...")
        
        # Load image config for base URL and mappings
        image_config = load_image_mappings()
        base_url = 'https://images.launchbox-app.com/'
        
        # Get boxart mapping from configuration
        launchbox_config = scrappers_config.get('launchbox', {})
        image_type_mappings = launchbox_config.get('image_type_mappings', {})
        boxart_types = image_type_mappings.get('boxart', ['Box - Front'])  # Fallback to old behavior
        
        # Look for boxart images in priority order
        if 'images' in game_metadata:
            print(f"🔍 DEBUG: Game has {len(game_metadata['images'])} images, looking for boxart types: {boxart_types}")
            for boxart_type in boxart_types:
                for image_element in game_metadata['images']:
                    # Handle dictionary format
                    image_type = image_element.get('Type', '').strip()
                    
                    # Check if this matches our boxart type
                    if image_type == boxart_type:
                        filename = image_element.get('FileName', '')
                        if filename:
                            full_url = base_url + filename
                            print(f"🔍 DEBUG: Found boxart image: {full_url}")
                            return full_url
        else:
            print(f"🔍 DEBUG: Game metadata has no 'images' field")
        
        return None
        
    except Exception as e:
        print(f"Error getting LaunchBox box image for ID {launchbox_id}: {e}")
        return None
async def download_launchbox_image_httpx(image_url, local_path, media_type=None, target_field=None, timeout=30, retry_attempts=10, client=None, game_name=None):
    """Download a single image from LaunchBox using HTTPX with HTTP/2 support"""
    import time
    import aiofiles
    
    headers = {
        'accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
        'accept-language': 'fr,en;q=0.9',
        'cache-control': 'no-cache',
        'dnt': '1',
        'pragma': 'no-cache',
        'priority': 'i',
        'referer': 'https://gamesdb.launchbox-app.com/',
        'sec-ch-ua': '"Not;A=Brand";v="99", "Google Chrome";v="139", "Chromium";v="139"',
        'sec-ch-ua-mobile': '?0',
        'sec-ch-ua-platform': '"Linux"',
        'sec-fetch-dest': 'image',
        'sec-fetch-mode': 'no-cors',
        'sec-fetch-site': 'same-site',
        'user-agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Safari/537.36'
    }
    
    filename = os.path.basename(local_path)
    media_info = f" [{media_type}]" if media_type else ""
    
    # Create prefix for logging with game name and media type
    prefix_parts = []
    if game_name:
        prefix_parts.append(game_name)
    if media_type:
        prefix_parts.append(media_type)
    
    log_prefix = f"[{' | '.join(prefix_parts)}]" if prefix_parts else ""
    
    # Track 0-size retries separately
    zero_size_retry_count = 0
    max_zero_size_retries = 2
    
    for attempt in range(retry_attempts):
        try:
            if attempt > 0:
                import threading
                threading.Thread(target=update_task_progress, args=(f"{log_prefix} 🔄 Retry {attempt + 1}/{retry_attempts}",), daemon=True).start()
            
            # Ensure directory exists
            os.makedirs(os.path.dirname(local_path), exist_ok=True)
            
            # Start timing for HTTP request with detailed metrics
            http_start_time = time.time()
            import threading
            threading.Thread(target=update_task_progress, args=(f"{log_prefix} ⏱️  Starting HTTPX HTTP/2 request to: {os.path.basename(image_url)} (attempt {attempt + 1}/{retry_attempts})",), daemon=True).start()
            
            # Use HTTPX client for async download with HTTP/2
            response = await client.get(image_url, headers=headers)
            response.raise_for_status()
            
            # Download the file
            bytes_written = 0
            async with aiofiles.open(local_path, 'wb') as f:
                async for chunk in response.aiter_bytes(chunk_size=8192):
                    await f.write(chunk)
                    bytes_written += len(chunk)
            
            # Verify file was created and has content
            if os.path.exists(local_path):
                file_size = os.path.getsize(local_path)
                if file_size > 0:
                    # Convert and/or resize image in a single operation (optimized)
                    # Use target_field parameter if available, otherwise fall back to media_type
                    field_to_check = target_field if target_field else media_type
                    from game_utils import should_process_field, convert_and_resize_image_replace
                    config = load_config()
                    should_process, target_extension, target_width, target_height = should_process_field(field_to_check, config)
                    
                    if should_process:
                        processed_path, process_status = convert_and_resize_image_replace(
                            local_path, target_extension, target_width, target_height
                        )
                        if process_status in ["converted", "resized", "converted_and_resized"]:
                            local_path = processed_path
                            filename = os.path.basename(local_path)
                            # Re-check file size after processing
                            if os.path.exists(local_path):
                                file_size = os.path.getsize(local_path)
                                if file_size == 0:
                                    # Processed file is 0 size, delete it
                                    try:
                                        os.remove(local_path)
                                        print(f"⚠️ Warning: Processed file is empty, deleted: {filename}")
                                    except Exception as e:
                                        print(f"⚠️ Warning: Failed to delete empty processed file: {e}")
                                    return False, f"Processed file is empty: {filename}"
                            print(f"✅ Processed image: {process_status} - {filename}")
                        elif process_status == "failed":
                            print(f"⚠️ Warning: Failed to process image: {filename}")
                    
                    return True, f"Downloaded {filename} ({file_size} bytes)"
                else:
                    # File is 0 size - delete it and retry
                    try:
                        os.remove(local_path)
                        print(f"⚠️ Warning: Downloaded file is 0 size (attempt {attempt + 1}), deleted: {filename}")
                    except Exception as e:
                        print(f"⚠️ Warning: Failed to delete empty file: {e}")
                    
                    # Retry for 0-size files (up to 2 additional retries)
                    zero_size_retry_count += 1
                    if zero_size_retry_count <= max_zero_size_retries and attempt < retry_attempts - 1:
                        import threading
                        threading.Thread(target=update_task_progress, args=(f"{log_prefix} ⚠️ File is 0 size, retrying download ({zero_size_retry_count}/{max_zero_size_retries})...",), daemon=True).start()
                        # Small delay before retry
                        await asyncio.sleep(1)
                        continue  # Retry the download
                    else:
                        # Max retries reached for 0-size files
                        return False, f"File is 0 size after {zero_size_retry_count} retries: {filename}"
            else:
                return False, f"File not created: {filename}"
            
        except httpx.RequestError as e:
            if attempt < retry_attempts - 1:
                # Exponential backoff: 1s, 2s, 4s, 8s, etc. (capped at 10s)
                retry_delay = min(2 ** attempt, 10)
                import threading
                threading.Thread(target=update_task_progress, args=(f"{log_prefix} ⏳ Waiting {retry_delay}s before retry {attempt + 1}/{retry_attempts}",), daemon=True).start()
                await asyncio.sleep(retry_delay)
            else:
                return False, f"Connection failed after {retry_attempts} attempts: {e}"
        except Exception as e:
            return False, f"Error: {e}"
    
    return False, f"Failed after {retry_attempts} attempts"

def get_region_priority_from_game_name(game_name, default_priority):
    """
    Extract region information from game name (in parentheses) and adjust priority.
    If no region is found or doesn't match known regions, return default priority.
    
    Args:
        game_name: The game name to analyze
        default_priority: Default region priority list from config
    
    Returns:
        List of regions in priority order, with detected region moved to front
    """
    if not game_name:
        return default_priority
    
    import re
    
    # Common region mappings
    region_mappings = {
        # North America variations
        'usa': 'North America',
        'us': 'North America', 
        'america': 'North America',
        'north america': 'North America',
        'na': 'North America',
        'canada': 'North America',
        'canadian': 'North America',
        
        # Europe variations
        'europe': 'Europe',
        'eu': 'Europe',
        'european': 'Europe',
        'uk': 'Europe',
        'england': 'Europe',
        'france': 'Europe',
        'french': 'Europe',
        'germany': 'Europe',
        'german': 'Europe',
        'italy': 'Europe',
        'italian': 'Europe',
        'spain': 'Europe',
        'spanish': 'Europe',
        'netherlands': 'Europe',
        'dutch': 'Europe',
        'sweden': 'Europe',
        'swedish': 'Europe',
        'norway': 'Europe',
        'norwegian': 'Europe',
        'denmark': 'Europe',
        'danish': 'Europe',
        'finland': 'Europe',
        'finnish': 'Europe',
        'poland': 'Europe',
        'polish': 'Europe',
        'russia': 'Europe',
        'russian': 'Europe',
        
        # Japan variations
        'japan': 'Japan',
        'japanese': 'Japan',
        'jp': 'Japan',
        'jpn': 'Japan',
        
        # World variations
        'world': 'World',
        'international': 'World',
        'intl': 'World',
        'global': 'World'
    }
    
    # Look for text in parentheses
    parentheses_match = re.search(r'\(([^)]+)\)', game_name)
    if not parentheses_match:
        return default_priority
    
    region_text = parentheses_match.group(1).lower().strip()
    
    # Try to find a matching region
    detected_region = None
    for key, region in region_mappings.items():
        if key in region_text:
            detected_region = region
            break
    
    # If no region detected, return default priority
    if not detected_region:
        return default_priority
    
    # Create new priority list with detected region moved to front
    new_priority = [detected_region]
    
    # Add other regions in their original order, excluding the detected one
    for region in default_priority:
        if region != detected_region:
            new_priority.append(region)
    
    return new_priority

async def get_game_images_from_launchbox_async(game_launchbox_id, image_config, system_path, rom_filename, game_name=None, current_game_data=None, force_download=False, media_config=None, region_config=None, selected_fields=None):
    """Get available images for a game from LaunchBox metadata and download them using aiohttp"""
    import time
    
    # Create game name prefix for logging
    game_prefix = f"[{game_name or rom_filename}]" if game_name or rom_filename else ""
    
    downloaded_images = []
    # Use passed configs (already validated at task start)
    media_fields = media_config.get('media_fields', {})

    
    # Check which fields need images based on current gamelist data
    fields_to_download = []
    if current_game_data and not force_download:
        for field_name in image_config.get('image_type_mappings', {}).keys():
            current_value = current_game_data.get(field_name)
            # Consider field empty if it's None, empty string, or just whitespace
            if not current_value or (isinstance(current_value, str) and current_value.strip() == ''):
                fields_to_download.append(field_name)
        
        if not fields_to_download:
            return []
        
    else:
        fields_to_download = list(image_config.get('image_type_mappings', {}).keys())
    
    # Create reverse mapping from gamelist field to LaunchBox image types
    field_to_launchbox_types = {}
    for gamelist_field, launchbox_types in image_config.get('image_type_mappings', {}).items():
        field_to_launchbox_types[gamelist_field] = launchbox_types
    
    # Filter fields_to_download to only include selected media fields
    print(f"🔧 DEBUG: selected_fields: {selected_fields}")
    print(f"🔧 DEBUG: fields_to_download before filtering: {fields_to_download}")
    if selected_fields is not None and len(selected_fields) > 0:
        # Only download fields that are in the selected_fields list
        fields_to_download = [field for field in fields_to_download if field in selected_fields]
        print(f"🔧 DEBUG: fields_to_download after filtering: {fields_to_download}")
    elif selected_fields is not None and len(selected_fields) == 0:
        # If selected_fields is explicitly empty, don't download any media
        fields_to_download = []
        print(f"🔧 DEBUG: selected_fields is empty, no downloads")
    else:
        print(f"🔧 DEBUG: selected_fields is None, using all fields")
    
    try:
        # Get GameImage entries from consolidated cache (already loaded)
        # Try both string and integer keys
        game_metadata = global_metadata_cache.get(game_launchbox_id)
        if not game_metadata:
            # Try with string conversion
            game_metadata = global_metadata_cache.get(str(game_launchbox_id))
        if not game_metadata:
            # Try with integer conversion
            try:
                game_metadata = global_metadata_cache.get(int(game_launchbox_id))
            except (ValueError, TypeError):
                pass
        
        all_game_images = (game_metadata or {}).get('images', [])
        
        # Use region configuration (already loaded at task start)
        default_region_priority = region_config.get('priority', ['World', 'North America', 'Europe', 'Japan'])
        
        # Try to extract region from game name and adjust priority
        region_priority = get_region_priority_from_game_name(game_name, default_region_priority)
        
        # Log region priority adjustment if it changed
        if region_priority != default_region_priority:
            print(f"{game_prefix} 🌍 Region priority adjusted based on game name: {region_priority}")
        else:
            print(f"{game_prefix} 🌍 Using default region priority: {region_priority}")
        
        # Filter GameImage entries to only include types that map to fields we need
        image_type_mappings = image_config.get('image_type_mappings', {})
        needed_image_types = set()
        
        # Create mapping from gamelist field to LaunchBox image types (with priority order)
        field_to_launchbox_types = {}
        for gamelist_field, launchbox_types in image_type_mappings.items():
            if gamelist_field in fields_to_download:
                field_to_launchbox_types[gamelist_field] = launchbox_types
                # Add all possible image types for this field to needed types
                for launchbox_type in launchbox_types:
                    needed_image_types.add(launchbox_type)
        
        
        # Filter and group only the needed images by type
        images_by_type = {}
        filtered_count = 0
        
        for game_image in all_game_images:
            # Handle dictionary-based image data (new format)
            image_type_text = game_image.get('Type', '')
            if not image_type_text:
                continue
                
            image_type_text = str(image_type_text).strip()
            
            # Only process image types that map to fields we need
            if image_type_text not in needed_image_types:
                continue
                
            filename_text = game_image.get('FileName', '')
            region_text = game_image.get('Region', 'Unknown')
            
            if filename_text:
                filename_text = str(filename_text).strip()
                region_text = str(region_text).strip() if region_text else 'Unknown'
                
                if image_type_text not in images_by_type:
                    images_by_type[image_type_text] = []
                
                images_by_type[image_type_text].append({
                    'filename': filename_text,
                    'region': region_text,
                    'element': game_image
                })
                filtered_count += 1
        
        
        # Prepare download tasks for parallel execution
        download_tasks = []
        
        # Process each field that needs images
        for gamelist_field in fields_to_download:
            # Get the priority-ordered list of LaunchBox image types for this field
            launchbox_types = field_to_launchbox_types.get(gamelist_field, [])
            
            # Find the first available image type in priority order
            best_image = None
            best_image_type = None
            
            for launchbox_type in launchbox_types:
                if launchbox_type in images_by_type and images_by_type[launchbox_type]:
                    type_images = images_by_type[launchbox_type]
                    
                    # Sort images by region priority
                    sorted_images = []
                    for img in type_images:
                        try:
                            region_index = region_priority.index(img['region'])
                        except ValueError:
                            region_index = len(region_priority)  # Unknown regions go last
                        sorted_images.append((region_index, img))
                    
                    sorted_images.sort(key=lambda x: x[0])  # Sort by region priority index
                    
                    # Select the best image (first in priority order)
                    best_image = sorted_images[0][1]
                    best_image_type = launchbox_type
                    break  # Stop at first available image type in priority order
            
            # Only create download task if we found an image
            if best_image and best_image_type:
                # Map gamelist field to media directory using new structure
                media_directory = get_media_directory(gamelist_field)
                
                if not media_directory:
                    continue  # Skip if no media directory mapping found
                
                # Construct download URL and local path
                base_url = 'https://images.launchbox-app.com/'
                download_url = base_url + best_image['filename']
                file_extension = os.path.splitext(best_image['filename'])[1]
                # Get ROM path from current_game_data
                rom_path = current_game_data.get('path', '') if current_game_data else ''
                local_filename = create_media_filename(rom_path, file_extension)
                local_path = os.path.join(system_path, 'media', media_directory, local_filename)
                
                # Create media directory if it doesn't exist
                media_dir = os.path.join(system_path, 'media', media_directory)
                os.makedirs(media_dir, exist_ok=True)
                
                # Add download task to the list
                download_tasks.append({
                    'gamelist_field': gamelist_field,
                    'download_url': download_url,
                    'local_path': local_path,
                    'media_type': best_image_type,
                    'target_field': gamelist_field,  # Add target field for PNG conversion
                    'region': best_image['region'],
                    'filename': best_image['filename'],
                    'media_directory': media_directory,
                    'local_filename': local_filename,
                    'game_name': game_name or rom_filename
                })
        
        
        import threading
        import queue
        
        # Create thread-safe queues for producer-consumer pattern
        download_queue = queue.Queue()  # Producer fills this with download tasks
        result_queue = queue.Queue()    # Consumer puts results here
        shutdown_event = threading.Event()  # Signal to shutdown consumer thread
        
        # Create HTTPX client configuration with HTTP/2 support
        limits = httpx.Limits(
            max_connections=20,  # Total connection pool size
            max_keepalive_connections=20,  # Max keepalive connections
            keepalive_expiry=30.0  # Keepalive expiry in seconds
        )
        
        timeout = httpx.Timeout(
            timeout=60.0,  # Total timeout
            connect=10.0,  # Connect timeout
            read=30.0      # Read timeout
        )
        
        # Create HTTPX headers for image downloads
        headers = {
            'accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
            'accept-language': 'fr,en;q=0.9',
            'cache-control': 'no-cache',
            'dnt': '1',
            'pragma': 'no-cache',
            'priority': 'i',
            'referer': 'https://gamesdb.launchbox-app.com/',
            'sec-ch-ua': '"Not;A=Brand";v="99", "Google Chrome";v="139", "Chromium";v="139"',
            'sec-ch-ua-mobile': '?0',
            'sec-ch-ua-platform': '"Linux"',
            'sec-fetch-dest': 'image',
            'sec-fetch-mode': 'no-cors',
            'sec-fetch-site': 'same-site',
            'user-agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Safari/537.36'
        }
        
        # No authentication - use unauthenticated session
        cookies = None
        
        # Use global download manager instead of creating new consumer threads
        from download_manager import get_download_manager
        
        download_manager = get_download_manager()
        # Start the download manager with cookies if this is the first time
        if cookies:
            download_manager.start(cookies)

        
        # Add tasks to the global download manager
        for task in download_tasks:
            # Log download attempt asynchronously (non-blocking)
            gamelist_field = task.get('gamelist_field', 'unknown')
            region = task.get('region', 'unknown')
            filename = task.get('filename', 'unknown')
            # Use threading for non-blocking logging
            import threading
            log_message = f"{game_prefix} Downloading {gamelist_field} ('{region}')"
            threading.Thread(target=update_task_progress, args=(log_message,), daemon=True).start()
            download_manager.add_task(task)
        
        
        # Collect results from the global download manager with stop checking
        results = []
        try:
            results = download_manager.wait_for_completion(len(download_tasks))
        except Exception as e:
            if is_task_stopped():
                import threading
                threading.Thread(target=update_task_progress, args=("🛑 Task stopped by user - stopping download manager",), daemon=True).start()
                download_manager.stop()
                return []
            else:
                raise e
        
        # Process results
        for result in results:
            if result and result.get('success'):
                # Log success message
#                gamelist_field = result.get('gamelist_field', 'unknown')
#                local_filename = result.get('local_path', '').split('/')[-1] if result.get('local_path') else 'unknown'
#                update_task_progress(f"{game_prefix} ✅ Success: {gamelist_field} → {local_filename}")
                
                downloaded_images.append({
                    'field': result['gamelist_field'],
                    'local_path': result['local_path'],
                    'message': result['message']
                })
            elif result:
                # Log failure message asynchronously (non-blocking)
                gamelist_field = result.get('gamelist_field', 'unknown')
                error_message = result.get('message', 'Unknown error')
                # Use threading for non-blocking logging
                import threading
                log_message = f"{game_prefix} ❌ Failed: {error_message}"
                threading.Thread(target=update_task_progress, args=(log_message,), daemon=True).start()
        
        return downloaded_images
        
    except Exception as e:
        print(f"Error processing LaunchBox images for game {game_launchbox_id}: {e}")
        if game_name or rom_filename:
            game_prefix = f"[{game_name or rom_filename}]"
            import threading
            threading.Thread(target=update_task_progress, args=(f"{game_prefix} ❌ Error: {e}",), daemon=True).start()
        return downloaded_images

def get_game_images_from_launchbox(game_launchbox_id, image_config, system_path, rom_filename, game_name=None, current_game_data=None, force_download=False, media_config=None, region_config=None, selected_fields=None):
    """Synchronous wrapper for get_game_images_from_launchbox_async"""
    import asyncio
    
    # Create a new event loop for this thread if needed
    try:
        loop = asyncio.get_event_loop()
    except RuntimeError:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
    
    # Run the async function in the event loop
    return loop.run_until_complete(
        get_game_images_from_launchbox_async(
            game_launchbox_id, image_config, system_path, rom_filename, 
            game_name, current_game_data, force_download, media_config, region_config, selected_fields
        )
    )

def scan_media_files(system_name):
    """Scan media files for a specific system and update gamelist.xml"""
    global current_task_id
    
    try:
        if not current_task_id or current_task_id not in tasks:
            print("Error: No active task found for media scan")
            return {'error': 'No active task found'}
        
        task = tasks[current_task_id]
        
        # Initialize task state
        task.update_progress("Starting media scan")
        
        media_config = load_media_config()
        if not media_config:
            task.update_progress("Failed to load media configuration")
            return {'error': 'Failed to load media configuration'}
        
        system_path = os.path.join(ROMS_FOLDER, system_name)
        task.update_progress(f"System path: {system_path}")
        if not os.path.exists(system_path):
            task.update_progress(f"System path does not exist: {system_path}")
            return {'error': 'System not found'}
        
        # Get gamelist path from var/gamelists
        gamelist_path = get_gamelist_path(system_name)
        task.update_progress(f"Gamelist path: {gamelist_path}")
        if not os.path.exists(gamelist_path):
            task.update_progress(f"Gamelist does not exist: {gamelist_path}")
            return {'error': 'Gamelist not found'}
        
        # Parse existing gamelist
        games = parse_gamelist_xml(gamelist_path)
        if not games:
            task.update_progress("No games found in gamelist")
            return {'error': 'No games found in gamelist'}
        
        task.update_progress(f"Found {len(games)} games in gamelist")
        
        # Load media fields
        media_fields = media_config.get('media_fields', {})
        task.update_progress(f"Media fields: {media_fields}")
        
        # Track changes
        updated_games = 0
        removed_media = 0
        
        # Check media directory structure
        media_base_dir = os.path.join(system_path, 'media')
        task.update_progress(f"Media base directory: {media_base_dir}")
        if os.path.exists(media_base_dir):
            task.update_progress(f"Media base directory exists, contents: {os.listdir(media_base_dir)}")
        else:
            task.update_progress(f"Media base directory does not exist: {media_base_dir}")
        
        # Process each game
        for i, game in enumerate(games):
            game_updated = False
            rom_path = game.get('path', '')
            
            if not rom_path:
                continue
            
            # Extract ROM filename without extension
            rom_filename = os.path.splitext(os.path.basename(rom_path))[0]
            
            # Ensure all expected media fields exist in the game data
            # Use the same field names that the scraper expects (from consolidated config.json)
            config = load_config()
            media_fields = config.get('media_fields', {})
            scraper_media_fields = list(media_fields.keys())
            missing_fields = []
            none_fields = []
            
            for field in scraper_media_fields:
                if field not in game:
                    game[field] = ''  # Initialize missing media fields as empty
                    game_updated = True
                    missing_fields.append(field)
                elif game[field] is None:
                    game[field] = ''  # Convert None to empty string
                    game_updated = True
                    none_fields.append(field)
            
            # Log grouped messages for missing fields
            if missing_fields:
                task.update_progress(f"Added missing media fields for '{game.get('name', 'Unknown')}': {', '.join(missing_fields)}")
            if none_fields:
                task.update_progress(f"Converted None to empty string for fields in '{game.get('name', 'Unknown')}': {', '.join(none_fields)}")
            
            # First, validate existing media fields and clean up broken references
            for gamelist_field, field_data in media_fields.items():
                current_media = game.get(gamelist_field, '')
                if current_media:
                    # Check if the existing media file still exists
                    if current_media.startswith('./media/'):
                        # Extract the relative path and check if file exists
                        relative_path = current_media[2:]  # Remove './'
                        full_path = os.path.join(system_path, relative_path)
                        if not os.path.exists(full_path):
                            # Media file doesn't exist, remove the reference
                            game[gamelist_field] = ''
                            game_updated = True
                            removed_media += 1
                            task.update_progress(f"Removed broken {gamelist_field} for '{game.get('name', 'Unknown')}': {current_media}")
            
            # Then, only add new media if the field is currently empty
            for gamelist_field, field_data in media_fields.items():
                current_media = game.get(gamelist_field, '')
                
                # Only look for new media if the field is empty
                if not current_media:
                    media_type = field_data['directory']
                    media_dir = os.path.join(system_path, 'media', media_type)
                    
                    # Look for media files with matching name
                    found_media = None
                    if os.path.exists(media_dir):
                        for ext in field_data.get('extensions', []):
                            media_filename = create_media_filename(rom_path, ext)
                            media_file = os.path.join(media_dir, media_filename)
                            if os.path.exists(media_file):
                                found_media = f'./media/{media_type}/{media_filename}'
                                break
                    
                    # Only add new media if field is empty and we found media
                    if found_media:
                        game[gamelist_field] = found_media
                        game_updated = True
                        task.update_progress(f"Added {gamelist_field} for '{game.get('name', 'Unknown')}': {found_media}")
            
            # Also check for orphaned media entries that might not be in the media_fields
            # This handles cases where the gamelist has media fields that aren't in the current config
            # Get additional media fields from config that might not be in the current media_fields
            config = load_config()
            all_media_fields = config.get('media_fields', {})
            orphaned_media_fields = list(all_media_fields.keys())
            
            for field in orphaned_media_fields:
                if field in game and game[field]:
                    # Check if this media file actually exists
                    media_path = game[field]
                    if media_path.startswith('./media/'):
                        # Extract the relative path and check if file exists
                        relative_path = media_path[2:]  # Remove './'
                        full_path = os.path.join(system_path, relative_path)
                        if not os.path.exists(full_path):
                            # Media file doesn't exist, remove the reference
                            game[field] = ''
                            game_updated = True
                            removed_media += 1
                            task.update_progress(f"Removed orphaned {field} for '{game.get('name', 'Unknown')}': {media_path}")
            
            if game_updated:
                updated_games += 1
            
            # Add progress indicator every 100 games
            if (i + 1) % 100 == 0:
                task.update_progress(f"Processed {i + 1} / {len(games)} games...")
        
        task.update_progress(f"Scan completed. Updated {updated_games} games, removed {removed_media} invalid media references.")
        
        # Always save the gamelist (even if no updates, to ensure consistency)
        try:
            write_gamelist_xml(games, gamelist_path)
            task.update_progress("Gamelist saved successfully")
            
            # Notify all connected clients about the gamelist update
            notify_gamelist_updated(system_name, len(games))
            
        except Exception as e:
            task.update_progress(f"ERROR saving gamelist: {e}")
            return {'error': f'Failed to save gamelist: {str(e)}'}
        
        return {
            'success': True,
            'message': f'Media scan completed. Updated {updated_games} games, removed {removed_media} invalid media references.',
            'updated_games': updated_games,
            'removed_media': removed_media,
            'total_games': len(games)
        }
        
    except Exception as e:
        print(f"Error scanning media files: {e}")
        import traceback
        traceback.print_exc()
        
        return {'error': f'Media scan failed: {str(e)}'}

def save_gamelist_xml(file_path, games):
    """Save games list to gamelist.xml file"""
    try:
        print(f"Saving gamelist.xml to {file_path} with {len(games)} games")
        
        # Deduplicate by path before saving to avoid duplicate entries
        games = _dedupe_games_by_path(games)

        # Create root element
        root = ET.Element('gameList')
        
        # Add each game
        for i, game in enumerate(games):
            game_elem = ET.SubElement(root, 'game')
            
            # Add all fields from the game data
            for field, value in game.items():
                # Handle boolean fields - convert to lowercase string
                if field in ['favorite', 'kidgame']:
                    if value == 'true' or value is True:
                        value = 'true'
                    elif value == 'false' or value is False:
                        value = 'false'
                    else:
                        # Keep empty string as empty (don't convert to 'false')
                        value = ''
                
                elem = ET.SubElement(game_elem, field)
                elem.text = html.escape(str(value), quote=False) if value else ''
        
        # Create XML tree and save
        tree = ET.ElementTree(root)
        
        # Save the file with proper formatting
        # First write to a temporary string to get the raw XML
        import io
        xml_string = io.BytesIO()
        tree.write(xml_string, encoding='utf-8', xml_declaration=True)
        xml_content = xml_string.getvalue().decode('utf-8')
        
        # Format the XML content for better readability
        formatted_xml = format_xml_for_readability(xml_content)
        
        # Write the formatted XML to file
        with open(file_path, 'w', encoding='utf-8') as f:
            f.write(formatted_xml)
        print(f"Successfully saved gamelist.xml with {len(games)} games")
        
        # Verify the file was written
        if os.path.exists(file_path):
            file_size = os.path.getsize(file_path)
            print(f"File saved successfully. Size: {file_size} bytes")
        else:
            print("ERROR: File was not created!")
            
    except Exception as e:
        print(f"Error saving gamelist.xml: {e}")
        import traceback
        traceback.print_exc()
        raise

def format_xml_for_readability(xml_content):
    """Format XML content to be more human-readable with proper line breaks and indentation using lxml's pretty_print"""
    try:
        # Parse the XML content (remove encoding declaration for lxml compatibility)
        xml_content_clean = xml_content
        if xml_content.startswith('<?xml'):
            # Find the end of the XML declaration
            end_decl = xml_content.find('?>')
            if end_decl != -1:
                xml_content_clean = xml_content[end_decl + 2:].strip()
        
        # Parse XML and use lxml's pretty_print
        root = ET.XML(xml_content_clean)
        
        # Use BytesIO to get proper XML declaration with pretty_print
        import io
        xml_bytes = io.BytesIO()
        ET.ElementTree(root).write(xml_bytes, pretty_print=True, encoding='utf-8', xml_declaration=True)
        formatted_xml = xml_bytes.getvalue().decode('utf-8')
        
        return formatted_xml
        
    except Exception as e:
        print(f"Error formatting XML: {e}")
        # Return original content if formatting fails
        return xml_content
def save_formatted_gamelist_xml(tree, gamelist_path):
    """Save gamelist.xml with proper formatting using the common formatting function"""
    try:
        # Write to a temporary string to get the raw XML
        import io
        xml_bytes = io.BytesIO()
        tree.write(xml_bytes, encoding='utf-8', xml_declaration=True)
        xml_content = xml_bytes.getvalue().decode('utf-8')
        
        # Verify the XML content is complete
        if not xml_content.strip():
            raise Exception("Generated XML content is empty")
        
        # Check if XML is properly closed
        if not xml_content.strip().endswith('</gameList>'):
            raise Exception("Generated XML content is incomplete - missing closing tag")
        
        # Format the XML content for better readability
        formatted_xml = format_xml_for_readability(xml_content)
        
        # Verify formatted XML is complete
        if not formatted_xml.strip():
            raise Exception("Formatted XML content is empty")
        
        if not formatted_xml.strip().endswith('</gameList>'):
            raise Exception("Formatted XML content is incomplete - missing closing tag")
        
        # Write the formatted XML to file atomically
        temp_path = f"{gamelist_path}.tmp.{int(time.time())}"
        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                f.write(formatted_xml)
                f.flush()  # Ensure data is written to disk
                os.fsync(f.fileno())  # Force OS to write to disk
            
            # Verify the written file
            if os.path.getsize(temp_path) == 0:
                raise Exception("Written file is empty")
            
            # Move temp file to final location
            import shutil
            shutil.move(temp_path, gamelist_path)
            
            # Final verification
            if not os.path.exists(gamelist_path):
                raise Exception("Final file does not exist after move")
            
            if os.path.getsize(gamelist_path) == 0:
                raise Exception("Final file is empty")
            
            print(f"Successfully saved formatted gamelist.xml to {gamelist_path} ({os.path.getsize(gamelist_path)} bytes)")
            
        except Exception as write_error:
            # Clean up temp file if it exists
            if os.path.exists(temp_path):
                os.remove(temp_path)
            raise write_error
        
    except Exception as e:
        print(f"Error saving formatted gamelist.xml: {e}")
        # Fallback to direct write if formatting fails
        try:
            tree.write(gamelist_path, encoding='utf-8', xml_declaration=True)
            print(f"Fallback: Direct write completed to {gamelist_path}")
        except Exception as fallback_error:
            print(f"Fallback write also failed: {fallback_error}")
            raise fallback_error


def format_releasedate_to_iso8601(date_input):
    """
    Format a release date to basic ISO 8601 date-time format (YYYYMMDDTHHMMSS).
    
    Args:
        date_input: Can be:
            - A datetime object
            - A timestamp (int/float)
            - A string in various formats (YYYY, YYYY-MM, YYYY-MM-DD, etc.)
            - A string already in YYYYMMDD format
    
    Returns:
        str: Formatted date in YYYYMMDDTHHMMSS format
        
    Examples:
        - "1990" -> "19900101T000000"
        - "1990-02" -> "19900201T000000" 
        - "1990-02-01" -> "19900201T000000"
        - "1990-02-01T12:30:45" -> "19900201T123045"
    """
    import datetime
    import re
    
    if date_input is None or date_input == '':
        return None
    
    # If it's already a datetime object
    if isinstance(date_input, datetime.datetime):
        return date_input.strftime('%Y%m%dT%H%M%S')
    
    # If it's a timestamp (int or float)
    if isinstance(date_input, (int, float)):
        try:
            dt = datetime.datetime.fromtimestamp(date_input)
            return dt.strftime('%Y%m%dT%H%M%S')
        except (ValueError, OSError):
            return None
    
    # If it's a string, try to parse it
    if isinstance(date_input, str):
        date_str = date_input.strip()
        
        # If already in YYYYMMDD format, add time
        if re.match(r'^\d{8}$', date_str):
            return f"{date_str}T000000"
        
        # If already in YYYYMMDDTHHMMSS format, return as is
        if re.match(r'^\d{8}T\d{6}$', date_str):
            return date_str
        
        # Try various date formats
        date_formats = [
            '%Y-%m-%dT%H:%M:%S',      # 1990-02-01T12:30:45
            '%Y-%m-%dT%H:%M:%S%z',    # 1990-02-01T12:30:45+00:00
            '%Y-%m-%dT%H:%M:%S.%f',   # 1990-02-01T12:30:45.123456
            '%Y-%m-%dT%H:%M:%S.%f%z', # 1990-02-01T12:30:45.123456+00:00
            '%Y-%m-%d %H:%M:%S',      # 1990-02-01 12:30:45
            '%Y-%m-%d',               # 1990-02-01
            '%Y/%m/%d',               # 1990/02/01
            '%m/%d/%Y',               # 02/01/1990
            '%d/%m/%Y',               # 01/02/1990
            '%d %b, %Y',              # 01 Feb, 1990 (Steam format)
            '%Y-%m',                  # 1990-02
            '%Y',                     # 1990
        ]
        
        for fmt in date_formats:
            try:
                dt = datetime.datetime.strptime(date_str, fmt)
                
                # If only year is provided, use first day of year
                if fmt == '%Y':
                    dt = dt.replace(month=1, day=1, hour=0, minute=0, second=0)
                # If only year-month is provided, use first day of month
                elif fmt == '%Y-%m':
                    dt = dt.replace(day=1, hour=0, minute=0, second=0)
                # If no time is provided, use midnight
                elif 'T' not in fmt and ' ' not in fmt:
                    dt = dt.replace(hour=0, minute=0, second=0)
                
                return dt.strftime('%Y%m%dT%H%M%S')
            except ValueError:
                continue
        
        # If all parsing attempts failed, return None
        return None
    
    return None


def format_releasedates_in_gamelist(gamelist_path):
    """
    Format all release dates in an existing gamelist.xml file to ISO 8601 format.
    
    Args:
        gamelist_path: Path to the gamelist.xml file to process
    """
    try:
        if not os.path.exists(gamelist_path):
            return False
        
        # Parse the XML file
        tree = ET.parse(gamelist_path)
        root = tree.getroot()
        
        if root.tag != 'gameList':
            print(f"Invalid gamelist format: expected 'gameList' root, got '{root.tag}' in {gamelist_path}")
            return False
        
        updated_count = 0
        
        # Process each game
        for game in root.findall('game'):
            releasedate_elem = game.find('releasedate')
            if releasedate_elem is not None and releasedate_elem.text:
                original_date = releasedate_elem.text.strip()
                if original_date:
                    # Format the release date
                    formatted_date = format_releasedate_to_iso8601(original_date)
                    if formatted_date and formatted_date != original_date:
                        releasedate_elem.text = formatted_date
                        updated_count += 1
        
        if updated_count > 0:
            # Save the updated gamelist
            save_formatted_gamelist_xml(tree, gamelist_path)
            print(f"📅 Formatted {updated_count} release dates in {gamelist_path}")
        
        return True
        
    except Exception as e:
        print(f"❌ Error formatting release dates in {gamelist_path}: {e}")
        return False


