def convert_cbz_to_pdf_response(cbz_path):
    """Convert CBZ file to PDF on-the-fly and return as response"""
    try:
        import pymupdf
        from PIL import Image
        import io
        import zipfile
        import tempfile
        
        # Open CBZ file (ZIP archive)
        with zipfile.ZipFile(cbz_path, 'r') as cbz_file:
            # Get list of files in the archive, sorted by name
            file_list = sorted(cbz_file.namelist())
            
            # Filter to only image files, sorted
            image_files = []
            for filename in file_list:
                lower_name = filename.lower()
                if (lower_name.endswith('.jpg') or lower_name.endswith('.jpeg') or 
                    lower_name.endswith('.png') or lower_name.endswith('.webp')):
                    # Skip hidden files and directories
                    if not os.path.basename(filename).startswith('.'):
                        image_files.append(filename)
            
            if not image_files:
                return jsonify({'error': 'No images found in CBZ file'}), 400
            
            # Create a new PDF document
            pdf_doc = pymupdf.open()
            
            # Add each image as a page in the PDF
            for image_file in image_files:
                try:
                    # Extract image to memory
                    image_data = cbz_file.read(image_file)
                    img = Image.open(io.BytesIO(image_data))
                    
                    # Convert to RGB if necessary
                    if img.mode != 'RGB':
                        img = img.convert('RGB')
                    
                    # Save image to temporary bytes
                    img_bytes = io.BytesIO()
                    img.save(img_bytes, format='PNG')
                    img_bytes.seek(0)
                    
                    # Create PDF page with image
                    page_rect = pymupdf.Rect(0, 0, img.width, img.height)
                    page = pdf_doc.new_page(width=img.width, height=img.height)
                    
                    # Insert image into page
                    page.insert_image(page_rect, stream=img_bytes.getvalue())
                    
                except Exception as e:
                    print(f"Warning: Failed to add image {image_file} to PDF: {e}")
                    continue
            
            if len(pdf_doc) == 0:
                pdf_doc.close()
                return jsonify({'error': 'Failed to create PDF from CBZ'}), 500
            
            # Save PDF to temporary file
            temp_fd, temp_path = tempfile.mkstemp(suffix='.pdf', prefix='cbz_')
            try:
                pdf_doc.save(temp_path)
                pdf_doc.close()
                
                # Read the temporary PDF
                with open(temp_path, 'rb') as f:
                    pdf_data = f.read()
                
                # Delete temporary file
                os.close(temp_fd)
                os.unlink(temp_path)
                
                # Return PDF as response with CORS headers
                from flask import Response
                response = Response(
                    pdf_data,
                    mimetype='application/pdf',
                    headers={
                        'Access-Control-Allow-Origin': '*',
                        'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
                        'Access-Control-Allow-Headers': 'Content-Type, Range',
                        'Accept-Ranges': 'bytes',
                        'Content-Length': str(len(pdf_data))
                    }
                )
                return response
            except Exception as e:
                pdf_doc.close()
                if os.path.exists(temp_path):
                    try:
                        os.close(temp_fd)
                        os.unlink(temp_path)
                    except:
                        pass
                raise e
                
    except zipfile.BadZipFile:
        return jsonify({'error': 'Invalid CBZ file (not a valid ZIP archive)'}), 400
    except Exception as e:
        print(f"Error converting CBZ to PDF: {e}")
        import traceback
        print(traceback.format_exc())
        return jsonify({'error': f'Failed to convert CBZ to PDF: {str(e)}'}), 500

@app.route('/api/cbz/<system_name>/<path:cbz_path>')
@login_required
def serve_cbz_file(system_name, cbz_path):
    """Serve CBZ files directly for JSZip viewer with proper CORS headers."""
    try:
        # Sanitize path (remove leading ./ or /)
        cbz_path = cbz_path.replace('..', '').lstrip('/').lstrip('./')
        
        # Construct full CBZ path
        full_cbz_path = os.path.join('roms', system_name, cbz_path)
        
        # Normalize path
        full_cbz_path = os.path.normpath(full_cbz_path)
        
        # Security check
        abs_roms = os.path.abspath('roms')
        abs_cbz = os.path.abspath(full_cbz_path)
        if not abs_cbz.startswith(abs_roms):
            return jsonify({'error': 'Invalid CBZ path'}), 400
        
        if not os.path.exists(full_cbz_path):
            return jsonify({'error': 'CBZ file not found'}), 404
        
        if not cbz_path.lower().endswith('.cbz'):
            return jsonify({'error': 'File is not a CBZ file'}), 400
        
        # Serve CBZ file with CORS headers
        response = send_file(full_cbz_path, mimetype='application/zip')
        response.headers['Access-Control-Allow-Origin'] = '*'
        response.headers['Access-Control-Allow-Methods'] = 'GET, HEAD, OPTIONS'
        response.headers['Access-Control-Allow-Headers'] = 'Content-Type, Range'
        response.headers['Accept-Ranges'] = 'bytes'
        return response
        
    except Exception as e:
        print(f"Error serving CBZ: {e}")
        return jsonify({'error': f'Failed to serve CBZ: {str(e)}'}), 500

@app.route('/api/pdf/<system_name>/<path:pdf_path>')
@login_required
def serve_pdf_for_viewer(system_name, pdf_path):
    """Serve PDF files for EmbedPDF viewer with proper CORS headers. Converts CBZ to PDF on-the-fly if needed."""
    try:
        # Sanitize path (remove leading ./ or /)
        pdf_path = pdf_path.replace('..', '').lstrip('/').lstrip('./')
        
        # Construct full PDF path
        full_pdf_path = os.path.join('roms', system_name, pdf_path)
        
        # Normalize path
        full_pdf_path = os.path.normpath(full_pdf_path)
        
        # Security check
        abs_roms = os.path.abspath('roms')
        abs_pdf = os.path.abspath(full_pdf_path)
        if not abs_pdf.startswith(abs_roms):
            return jsonify({'error': 'Invalid PDF path'}), 400
        
        if not os.path.exists(full_pdf_path):
            return jsonify({'error': 'PDF file not found'}), 404
        
        # Check if it's a CBZ file - convert to PDF on-the-fly
        # Also support PDF/CBZ paths for map field (same as manual)
        if pdf_path.lower().endswith('.cbz'):
            return convert_cbz_to_pdf_response(full_pdf_path)
        elif not pdf_path.lower().endswith('.pdf'):
            return jsonify({'error': 'File is not a PDF or CBZ'}), 400
        
        # Serve PDF with CORS headers for EmbedPDF
        response = send_file(full_pdf_path, mimetype='application/pdf')
        response.headers['Access-Control-Allow-Origin'] = '*'
        response.headers['Access-Control-Allow-Methods'] = 'GET, HEAD, OPTIONS'
        response.headers['Access-Control-Allow-Headers'] = 'Content-Type, Range'
        response.headers['Accept-Ranges'] = 'bytes'
        return response
        
    except Exception as e:
        print(f"Error serving PDF: {e}")
        return jsonify({'error': f'Failed to serve PDF: {str(e)}'}), 500

@app.route('/api/pdf-preview-remote', methods=['POST'])
@login_required
def get_pdf_preview_remote():
    """Convert first page of remote PDF URL to JPG on-the-fly"""
    try:
        data = request.get_json()
        if not data or not data.get('url'):
            return jsonify({'error': 'URL is required'}), 400
        
        pdf_url = data.get('url')
        
        # Import pymupdf
        import pymupdf
        from PIL import Image
        import io
        import requests
        
        # Check if this is a ScreenScraper URL and add Referer header if needed
        headers = {}
        if 'screenscraper.fr' in pdf_url or 'screenscraper.fr' in pdf_url:
            # Extract game ID and system ID from URL
            # Format: https://www.screenscraper.fr/medias/<system_id>/<game_id>/manuel(us).pdf
            try:
                import re
                match = re.search(r'/medias/(\d+)/(\d+)/', pdf_url)
                if match:
                    screenscraper_system_id = match.group(1)
                    screenscraper_id = match.group(2)
                    # Construct Referer header URL
                    referer_url = f"https://www.screenscraper.fr/gameinfos.php?gameid={screenscraper_id}&action=onglet&zone=gameinfosmedias"
                    headers = {
                        'Referer': referer_url,
                        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
                    }
            except Exception as e:
                print(f"Warning: Could not extract ScreenScraper IDs from URL: {e}")
        
        # Download PDF from remote URL with headers if needed
        response = requests.get(pdf_url, headers=headers, timeout=10, stream=True)
        if response.status_code != 200:
            return jsonify({'error': f'Failed to fetch PDF: {response.status_code}'}), 404
        
        # Read PDF into memory
        pdf_data = io.BytesIO()
        for chunk in response.iter_content(chunk_size=8192):
            pdf_data.write(chunk)
        pdf_data.seek(0)
        
        # Open PDF from memory
        pdf_doc = pymupdf.open(stream=pdf_data.read(), filetype='pdf')
        if len(pdf_doc) == 0:
            pdf_doc.close()
            return jsonify({'error': 'PDF has no pages'}), 400
        
        # Get first page
        page = pdf_doc[0]
        
        # Render page to pixmap
        zoom = 2.0
        mat = pymupdf.Matrix(zoom, zoom)
        pix = page.get_pixmap(matrix=mat)
        
        # Convert to PIL Image
        img_data = pix.tobytes("ppm")
        img = Image.open(io.BytesIO(img_data))
        
        # Convert to RGB if necessary
        if img.mode != 'RGB':
            img = img.convert('RGB')
        
        # Resize to reasonable size
        max_size = 800
        if img.width > max_size or img.height > max_size:
            img.thumbnail((max_size, max_size), Image.Resampling.LANCZOS)
        
        # Save to memory buffer and return
        img_buffer = io.BytesIO()
        img.save(img_buffer, 'JPEG', quality=85)
        img_buffer.seek(0)
        
        # Close PDF
        pdf_doc.close()
        
        # Return image directly from memory
        return send_file(img_buffer, mimetype='image/jpeg')
        
    except ImportError as e:
        import sys
        python_path = sys.executable
        python_version = sys.version
        error_msg = (
            f'PyMuPDF not found. '
            f'Python: {python_path}, Version: {python_version}. '
            f'Install with: apt install python3-pymupdf or pip3 install pymupdf. '
            f'Error: {str(e)}'
        )
        return jsonify({'error': error_msg}), 500
    except Exception as e:
        print(f"Error generating PDF preview from remote URL: {e}")
        import traceback
        print(traceback.format_exc())
        return jsonify({'error': f'Failed to generate PDF preview: {str(e)}'}), 500

