@app.route('/api/pdf-preview/<system_name>/<path:pdf_path>')
@login_required
def get_pdf_preview(system_name, pdf_path):
    """Convert first page of PDF to JPG on-the-fly"""
    try:
        # Import pymupdf directly as recommended in the documentation
        # See https://pymupdf.readthedocs.io/en/latest/recipes-images.html
        import pymupdf
        
        from PIL import Image
        import io
        
        # Sanitize path (remove leading ./ or /)
        pdf_path = pdf_path.replace('..', '').lstrip('/').lstrip('./')
        
        # Construct full PDF path
        full_pdf_path = os.path.join('roms', system_name, pdf_path)
        
        # Normalize path to handle any path separators
        full_pdf_path = os.path.normpath(full_pdf_path)
        
        # Additional security check - ensure path doesn't escape roms directory
        # Convert to absolute path for comparison
        abs_roms = os.path.abspath('roms')
        abs_pdf = os.path.abspath(full_pdf_path)
        if not abs_pdf.startswith(abs_roms):
            return jsonify({'error': 'Invalid PDF path'}), 400
        
        if not os.path.exists(full_pdf_path):
            print(f"PDF file not found: {full_pdf_path}")
            return jsonify({'error': 'PDF file not found'}), 404
        
        # Open PDF and convert first page to image
        # Using pymupdf.open() as per documentation examples
        # See https://pymupdf.readthedocs.io/en/latest/recipes-images.html
        pdf_doc = pymupdf.open(full_pdf_path)
        if len(pdf_doc) == 0:
            pdf_doc.close()
            return jsonify({'error': 'PDF has no pages'}), 400
        
        # Get first page
        page = pdf_doc[0]
        
        # Render page to pixmap (use 2x zoom for better quality)
        # Using dpi parameter as recommended in documentation
        # See https://pymupdf.readthedocs.io/en/latest/recipes-images.html#how-to-increase-image-resolution
        zoom = 2.0
        mat = pymupdf.Matrix(zoom, zoom)
        pix = page.get_pixmap(matrix=mat)
        
        # Convert to PIL Image
        img_data = pix.tobytes("ppm")
        img = Image.open(io.BytesIO(img_data))
        
        # Convert to RGB if necessary (some PDFs might have alpha channel)
        if img.mode != 'RGB':
            img = img.convert('RGB')
        
        # Resize to reasonable size (max 800px width/height)
        max_size = 800
        if img.width > max_size or img.height > max_size:
            img.thumbnail((max_size, max_size), Image.Resampling.LANCZOS)
        
        # Save to memory buffer and return directly
        img_buffer = io.BytesIO()
        img.save(img_buffer, 'JPEG', quality=85)
        img_buffer.seek(0)
        
        # Close PDF
        pdf_doc.close()
        
        # Return image directly from memory
        return send_file(img_buffer, mimetype='image/jpeg')
        
    except ImportError as e:
        # Provide more detailed error information
        import sys
        python_path = sys.executable
        python_version = sys.version
        error_msg = (
            f'PyMuPDF (fitz) not found. '
            f'Python: {python_path}, Version: {python_version}. '
            f'Install with: apt install python3-pymupdf or pip3 install pymupdf. '
            f'Error: {str(e)}'
        )
        print(f"PDF preview import error: {error_msg}")
        return jsonify({'error': error_msg}), 500
    except Exception as e:
        print(f"Error generating PDF preview: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': f'Failed to generate PDF preview: {str(e)}'}), 500

# Authentication Routes
@app.route('/login', methods=['GET', 'POST'])
def login():
    # Check if authentication should be bypassed
    if should_bypass_auth():
        # Auto-login as admin user
        admin_user = get_or_create_admin_user()
        if admin_user:
            login_user(admin_user, remember=True)
            update_user_last_login(admin_user.id)
            flash('Logged in as admin (authentication bypassed)', 'info')
            next_page = request.args.get('next')
            return redirect(next_page) if next_page else redirect(url_for('index'))
        else:
            flash('Failed to create admin user for bypass authentication', 'error')
            return render_template('login.html', discord_only=True, discord_disabled=True, discord_enabled=False)
    
    # Check if local authentication is disabled
    if is_local_auth_disabled():
        if not is_discord_auth_enabled():
            flash('Authentication is not properly configured. Please contact an administrator.', 'error')
            return render_template('login.html', discord_only=True, discord_disabled=True, discord_enabled=False)
        else:
            # Redirect to Discord login if local auth is disabled
            return redirect(url_for('discord_login'))
    
    # Check if this is the first user (no users exist yet)
    if not users_exist():
        if request.method == 'POST':
            # Handle first user registration
            username = request.form.get('username')
            password = request.form.get('password')
            confirm_password = request.form.get('confirm_password')
            email = request.form.get('email', '')
            
            if not username or not password or not confirm_password:
                flash('Please fill in all required fields', 'error')
                return render_template('login.html', is_first_user=True, discord_only=False, discord_enabled=is_discord_auth_enabled())
            
            if password != confirm_password:
                flash('Passwords do not match', 'error')
                return render_template('login.html', is_first_user=True, discord_only=False, discord_enabled=is_discord_auth_enabled())
            
            if len(password) < 6:
                flash('Password must be at least 6 characters long', 'error')
                return render_template('login.html', is_first_user=True, discord_only=False, discord_enabled=is_discord_auth_enabled())
            
            # Create the first admin user
            admin_user, error = create_user(username, password, email)
            if admin_user:
                # Validate the first user immediately and make them admin
                users = load_users()
                if admin_user.id in users:
                    users[admin_user.id]['is_validated'] = True
                    save_users(users)
                    flash('First admin user created successfully! You can now log in.', 'success')
                    return redirect(url_for('login'))
                else:
                    flash('Failed to validate admin user', 'error')
            else:
                flash(f'Failed to create admin user: {error}', 'error')
        
        return render_template('login.html', is_first_user=True, discord_only=False, discord_enabled=is_discord_auth_enabled())
    
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        remember_me = request.form.get('remember_me')
        
        if not username or not password:
            flash('Please fill in all fields', 'error')
            return render_template('login.html', discord_only=False, discord_enabled=is_discord_auth_enabled())
        
        # Check if user exists and password is correct
        users = load_users()
        user = None
        for user_id, user_data in users.items():
            if user_data['username'] == username:
                if verify_password(password, user_data['password_hash']):
                    user = User(
                        user_id=user_id,
                        username=user_data['username'],
                        email=user_data.get('email'),
                        discord_id=user_data.get('discord_id'),
                        is_active=user_data.get('is_active', True),
                        is_validated=user_data.get('is_validated', False),
                        created_at=user_data.get('created_at'),
                        last_login=user_data.get('last_login')
                    )
                    break
        
        if user and user.is_active:
            if user.is_validated:
                print(f"Logging in user: {user.username}")
                print(f"Session before login: {dict(session)}")
                login_user(user, remember=remember_me)
                print(f"Session after login: {dict(session)}")
                update_user_last_login(user.id)
                flash(f'Welcome back, {user.username}!', 'success')
                next_page = request.args.get('next')
                return redirect(next_page) if next_page else redirect(url_for('index'))
            else:
                flash('Your account is pending validation. Please contact an administrator.', 'warning')
        else:
            flash('Invalid username or password', 'error')
    
    return render_template('login.html', discord_only=False, discord_enabled=is_discord_auth_enabled())


