@app.route('/api/change-password', methods=['POST'])
@login_required
def change_password():
    """Change user password (for local accounts only)"""
    try:
        # Check if user is a local account (not Discord)
        if current_user.discord_id:
            return jsonify({'success': False, 'message': 'Discord accounts cannot change password through this interface'})
        
        data = request.get_json()
        current_password = data.get('current_password')
        new_password = data.get('new_password')
        confirm_password = data.get('confirm_password')
        
        # Validate input
        if not all([current_password, new_password, confirm_password]):
            return jsonify({'success': False, 'message': 'All fields are required'})
        
        if new_password != confirm_password:
            return jsonify({'success': False, 'message': 'New passwords do not match'})
        
        if len(new_password) < 6:
            return jsonify({'success': False, 'message': 'New password must be at least 6 characters long'})
        
        # Load users and verify current password
        users = load_users()
        if current_user.id not in users:
            return jsonify({'success': False, 'message': 'User not found'})
        
        user_data = users[current_user.id]
        if not verify_password(current_password, user_data['password_hash']):
            return jsonify({'success': False, 'message': 'Current password is incorrect'})
        
        # Update password
        users[current_user.id]['password_hash'] = hash_password(new_password)
        save_users(users)
        
        return jsonify({'success': True, 'message': 'Password changed successfully'})
    
    except Exception as e:
        print(f"Error changing password: {e}")
        return jsonify({'success': False, 'message': 'Error changing password'})

def _matches_media_type(image_type, requested_media_type, media_directory):
    """Check if an image type matches the requested media type using config mappings"""
    # Load the LaunchBox configuration from config
    launchbox_config = scrappers_config.get('launchbox', {})
    image_type_mappings = launchbox_config.get('image_type_mappings', {})
    
    # Check if this image type maps to the requested media type
    # New structure: image_type_mappings[gamelist_field] = [list of launchbox_types]
    for gamelist_field, launchbox_types in image_type_mappings.items():
        if gamelist_field == requested_media_type and image_type in launchbox_types:
            return True
    
    return False

@app.route('/api/launchbox-media/<launchbox_id>/<media_type>', methods=['GET'])
@login_required
def get_launchbox_media(launchbox_id, media_type):
    """Get available media from LaunchBox database for a specific game and media type"""
    try:
        if not launchbox_id or launchbox_id == 'None':
            return jsonify({'error': 'LaunchBox ID is required'}), 400
        
        # Load media config to get media mappings
        media_config = load_media_config()
        
        # Debug logging
        print(f"DEBUG: media_type = {media_type}")
        print(f"DEBUG: media_fields = {media_config.get('media_fields', {})}")
        
        # Load image config for base URL
        image_config = load_image_mappings()
        
        # Find the media type mapping
        media_directory = get_media_directory(media_type)
        
        if not media_directory:
            return jsonify({'error': f'Unknown media type: {media_type}. Available fields: {list(media_config.get("media_fields", {}).keys())}'}), 400
        
        # Use the global global_metadata_cache (should already be loaded at startup)
        if not global_metadata_cache:
            # Fallback: load cache if not already loaded
            load_metadata_cache()
        
        # Get game metadata from global global_metadata_cache
        game_metadata = global_metadata_cache.get(launchbox_id)
        if not game_metadata:
            return jsonify({'error': 'Game not found in LaunchBox database'}), 404
        
        # Get available media for this type
        available_media = []
        
        # Handle video type separately - VideoURL is stored directly in metadata, not in images array
        if media_type == 'video':
            # Debug: Print available keys in game_metadata
            print(f"DEBUG: Checking video for launchbox_id={launchbox_id}")
            print(f"DEBUG: game_metadata keys: {list(game_metadata.keys())}")
            
            # Check for VideoURL in game_metadata (check multiple possible field names)
            video_url = (game_metadata.get('VideoURL') or 
                        game_metadata.get('videoURL') or 
                        game_metadata.get('video_url') or
                        game_metadata.get('Video Url'))
            
            print(f"DEBUG: video_url found: {video_url}")
            
            if video_url:
                available_media.append({
                    'url': video_url,  # VideoURL is already a full URL
                    'VideoURL': video_url,
                    'videoURL': video_url,
                    'video_url': video_url,
                    'filename': video_url,  # Use URL as filename for video
                    'region': game_metadata.get('Region', 'Unknown'),
                    'primary': True,
                    'type': 'Video'
                })
            else:
                print(f"DEBUG: No VideoURL found for launchbox_id={launchbox_id}")
        else:
            # The metadata structure has 'images' array containing dictionaries
            if game_metadata and 'images' in game_metadata:
                for image_element in game_metadata['images']:
                    # Handle dictionary format
                    image_type = image_element.get('Type', '').strip()
                    
                    # Check if this image type matches what we're looking for
                    if _matches_media_type(image_type, media_type, media_directory):
                        filename = image_element.get('FileName', '')
                        region = image_element.get('Region', 'Unknown')
                        
                        if filename:
                            base_url = 'https://images.launchbox-app.com/'
                            media_url = base_url + filename
                            
                            available_media.append({
                                'url': media_url,
                                'filename': filename,
                                'region': region,
                                'primary': False,  # We don't have primary info in this structure
                                'type': image_type
                            })
        
        # Sort by primary first, then by region
        available_media.sort(key=lambda x: (not x.get('primary', False), x.get('region', '')))
        
        return jsonify({
            'success': True,
            'media': available_media,
            'count': len(available_media)
        })
        
    except Exception as e:
        print(f"Error fetching LaunchBox media: {e}")
        return jsonify({'error': f'Failed to fetch media: {str(e)}'}), 500

@app.route('/api/generate-2d-box', methods=['POST'])
@login_required
def generate_2d_box():
    """Start 2D box generation task for selected games"""
    try:
        data = request.get_json()
        system_name = data.get('system_name')
        selected_games = data.get('selected_games', [])
        background_field = data.get('background_field')
        screen_field = data.get('screen_field')
        additional_screenshot_field = data.get('additional_screenshot_field')
        target_field = data.get('target_field')
        
        if not system_name or not selected_games:
            return jsonify({'error': 'Missing required parameters'}), 400
        
        if not background_field or not screen_field or not target_field:
            return jsonify({'error': 'Missing required field selections'}), 400
        
        # Add task to queue
        task = add_task_to_queue('2d_box_generation', {
            'system_name': system_name,
            'selected_games': selected_games,
            'background_field': background_field,
            'screen_field': screen_field,
            'additional_screenshot_field': additional_screenshot_field,
            'target_field': target_field
        })
        
        return jsonify({
            'success': True,
            'task_id': task.id,
            'games_count': len(selected_games)
        })
        
    except Exception as e:
        return jsonify({'error': f'Failed to start 2D box generation: {str(e)}'}), 500

@app.route('/api/save-box-template', methods=['POST'])
@login_required
def save_box_template():
    """Save a box template configuration"""
    try:
        template_name = request.form.get('template_name')
        if not template_name:
            return jsonify({'success': False, 'error': 'Template name is required'}), 400
        
        # Create templates directory if it doesn't exist
        templates_dir = 'var/2dbox/templates'
        os.makedirs(templates_dir, exist_ok=True)
        
        # Save background image
        background_file = request.files.get('background_image')
        
        if not background_file:
            return jsonify({'success': False, 'error': 'Background image is required'}), 400
        
        # Sanitize template name for filesystem
        safe_name = re.sub(r'[^\w\s-]', '', template_name).strip().replace(' ', '_')
        
        # Save background image
        background_filename = f'{safe_name}_background.jpg'
        background_path = os.path.join(templates_dir, background_filename)
        background_file.save(background_path)
        
        # Get corner positions
        corners_json = request.form.get('corners')
        corners = json.loads(corners_json) if corners_json else {}
        
        # Save template metadata as JSON
        template_data = {
            'name': template_name,
            'background_image': background_filename,  # Store relative path
            'corners': corners
        }
        
        template_json_path = os.path.join(templates_dir, f'{safe_name}.json')
        with open(template_json_path, 'w') as f:
            json.dump(template_data, f, indent=2)
        
        return jsonify({'success': True, 'message': 'Template saved successfully'})
        
    except Exception as e:
        return jsonify({'success': False, 'error': f'Failed to save template: {str(e)}'}), 500

