# Global httpx async client and rate limiter for IGDB API
_igdb_async_client = None
_igdb_manual_async_client = None
_igdb_rate_limiter = None

def get_igdb_rate_limiter():
    """Get or create global rate limiter for IGDB API"""
    global _igdb_rate_limiter
    if _igdb_rate_limiter is None:
        # Add current directory to Python path to find local pyrate_limiter
        import sys
        import os
        current_dir = os.path.dirname(os.path.abspath(__file__))
        if current_dir not in sys.path:
            sys.path.insert(0, current_dir)
        
        from pyrate_limiter import Limiter, Rate
        # Create rate limiter: 4 requests per second
        _igdb_rate_limiter = Limiter(Rate(4, 1.0))
        print("✅ IGDB rate limiter initialized (using local pyrate_limiter)")
    return _igdb_rate_limiter

def get_screenscraper_user_info(ssid, sspassword, devid, devpassword, force_refresh=False):
    """
    Get ScreenScraper user info with 24h caching
    Returns the maxthreads value for connection pool configuration
    
    Args:
        ssid: ScreenScraper user ID
        sspassword: ScreenScraper user password
        devid: ScreenScraper developer ID
        devpassword: ScreenScraper developer password
        force_refresh: Force refresh cache even if valid
    """
    import os
    import json
    import time
    from datetime import datetime, timedelta
    
    # Create cache directory
    cache_dir = "var/cache/screenscraper"
    os.makedirs(cache_dir, exist_ok=True)

    cache_file = os.path.join(cache_dir, "screenscraper_user_info.json")
    
    # Check if cache exists and is valid (24 hours)
    if not force_refresh and os.path.exists(cache_file):
        try:
            with open(cache_file, 'r') as f:
                cache_data = json.load(f)
            
            # Check if cache is still valid (24 hours)
            cache_time = datetime.fromisoformat(cache_data.get('timestamp', ''))
            cache_age = datetime.now() - cache_time
            if cache_age < timedelta(hours=24):
                hours_remaining = 24 - (cache_age.total_seconds() / 3600)
                print(f"📋 Using cached ScreenScraper user info (maxthreads: {cache_data.get('maxthreads', 2)}, expires in {hours_remaining:.1f}h)")
                return cache_data.get('maxthreads', 2)
            else:
                print(f"🔄 ScreenScraper user info cache expired ({cache_age.total_seconds()/3600:.1f}h old), refreshing...")
        except Exception as e:
            print(f"⚠️ Error reading ScreenScraper user info cache: {e}")
    
    # Fetch fresh data from API
    try:
        import requests
        api_url = f"https://api.screenscraper.fr/api2/ssuserInfos.php?ssid={ssid}&sspassword={sspassword}&devid={devid}&devpassword={devpassword}"
        
        print(f"🌐 Fetching ScreenScraper user info from API...")
        response = requests.get(api_url, timeout=30)
        response.raise_for_status()
        
        # Parse the response (it's likely XML or JSON)
        try:
            # Try JSON first
            data = response.json()
        except:
            # If not JSON, try to parse as XML and extract maxthreads
            try:
                root = ET.fromstring(response.content)  # Use response.content (bytes) instead of response.text
                data = {}
                for child in root:
                    if child.tag == 'maxthreads':
                        data['maxthreads'] = int(child.text)
                    elif child.tag == 'ssuser':
                        for user_child in child:
                            if user_child.tag == 'maxthreads':
                                data['maxthreads'] = int(user_child.text)
            except ET.ParseError:
                # If XML parsing fails, check for error messages
                if "Erreur de login" in response.text or "Vérifier les identifiants" in response.text:
                    print(f"⚠️ ScreenScraper login error: {response.text.strip()}")
                    return 2  # Return default value
                else:
                    print(f"⚠️ Unexpected ScreenScraper response: {response.text[:200]}...")
                    return 2  # Return default value
        
        maxthreads = data.get('maxthreads', 1)  # Default to 1 if not found
        
        # Cache the result
        cache_data = {
            'maxthreads': maxthreads,
            'timestamp': datetime.now().isoformat()
        }
        
        with open(cache_file, 'w') as f:
            json.dump(cache_data, f, indent=2)
        
        print(f"✅ ScreenScraper user info cached (maxthreads: {maxthreads}, expires in 24h)")
        return maxthreads
        
    except Exception as e:
        print(f"❌ Error fetching ScreenScraper user info: {e}")
        # Return default value if API fails
        return 2

async def get_igdb_async_client():
    """Get or create global httpx async client for IGDB API with rate limiting"""
    global _igdb_async_client
    if _igdb_async_client is None:
        import httpx
        rate_limiter = get_igdb_rate_limiter()
        
        # Create async client with HTTP/2 and connection pooling
        # Max 8 parallel connections, 4 requests per second rate limit
        _igdb_async_client = httpx.AsyncClient(
            http2=True,  # Enable HTTP/2 for better performance
            limits=httpx.Limits(
                max_connections=8,           # Maximum 8 parallel connections
                max_keepalive_connections=8, # Keep 8 connections alive
                keepalive_expiry=30.0        # Keep connections alive for 30 seconds
            ),
            timeout=httpx.Timeout(
                connect=10.0,  # 10 seconds to establish connection
                read=30.0,     # 30 seconds to read response
                write=10.0,    # 10 seconds to write request
                pool=5.0       # 5 seconds to get connection from pool
            )
        )
    
    return _igdb_async_client

async def get_igdb_manual_async_client():
    """Get or create httpx async client for IGDB manual scrap/multiscraper (no rate limiting)"""
    global _igdb_manual_async_client
    if _igdb_manual_async_client is None:
        import httpx
        
        # Create async client with HTTP/2 and connection pooling for manual operations
        # Max 8 parallel connections, NO rate limiting for faster manual scrap
        _igdb_manual_async_client = httpx.AsyncClient(
            http2=True,  # Enable HTTP/2 for better performance
            limits=httpx.Limits(
                max_connections=8,           # Maximum 8 parallel connections
                max_keepalive_connections=8, # Keep 8 connections alive
                keepalive_expiry=30.0        # Keep connections alive for 30 seconds
            ),
            timeout=httpx.Timeout(
                connect=5.0,   # 5 seconds to establish connection
                read=10.0,     # 10 seconds to read response
                write=5.0,     # 5 seconds to write request
                pool=3.0       # 3 seconds to get connection from pool
            )
        )
        print("✅ IGDB manual async client initialized (no rate limiting, 8 connections)")
    
    return _igdb_manual_async_client

async def close_igdb_async_client():
    """Close the global httpx async client"""
    global _igdb_async_client
    if _igdb_async_client is not None:
        await _igdb_async_client.aclose()
        _igdb_async_client = None

async def close_igdb_manual_async_client():
    """Close the manual httpx async client"""
    global _igdb_manual_async_client
    if _igdb_manual_async_client is not None:
        await _igdb_manual_async_client.aclose()
        _igdb_manual_async_client = None

async def igdb_rate_limited_post(async_client, url, headers=None, content=None, **kwargs):
    """Make a rate-limited POST request to IGDB API
    
    Rate limiting: 4 requests per second
    Connection pooling: Max 8 parallel connections with HTTP/2
    """
    import time
    start_time = time.time()
    
    # Log the request details
    print(f"🌐 HTTP REQUEST (RATE-LIMITED): POST {url}")
    print(f"🌐 Headers: {headers}")
    if content:
        print(f"🌐 Content: {content[:200]}{'...' if len(content) > 200 else ''}")
    
    rate_limiter = get_igdb_rate_limiter()
    
    # Acquire rate limit before making the request (4 req/sec)
    # Use a consistent identifier for rate limiting
    await rate_limiter.try_acquire_async('igdb_api_requests')
    
    # Make the actual request using the connection pool
    # The httpx client will handle connection pooling (max 8 parallel)
    try:
        response = await async_client.post(url, headers=headers, content=content, timeout=10.0, **kwargs)
    except Exception as e:
        print(f"🌐 HTTP REQUEST ERROR (RATE-LIMITED): {e}")
        raise e
    
    end_time = time.time()
    print(f"🌐 HTTP RESPONSE (RATE-LIMITED): {response.status_code} in {end_time - start_time:.3f}s")
    print(f"🌐 Response headers: {dict(response.headers)}")
    
    # Log response content (full content)
    try:
        response_text = response.text
        print(f"🌐 Response size: {len(response_text)} bytes")
        print(f"🌐 Response content: {response_text}")
    except Exception as e:
        print(f"🌐 Error reading response: {e}")
    
    return response

async def igdb_manual_post(async_client, url, headers=None, content=None, **kwargs):
    """Make a non-rate-limited POST request to IGDB API for manual scrap/multiscraper
    
    No rate limiting for faster manual operations
    Connection pooling: Max 8 parallel connections with HTTP/2
    """
    import time
    start_time = time.time()
    
    # Log the request details
    print(f"🌐 HTTP REQUEST: POST {url}")
    print(f"🌐 Headers: {headers}")
    if content:
        print(f"🌐 Content: {content}")
    
    # Make the request directly without rate limiting
    # The httpx client will handle connection pooling (max 8 parallel)
    try:
        response = await async_client.post(url, headers=headers, content=content, timeout=10.0, **kwargs)
    except Exception as e:
        print(f"🌐 HTTP REQUEST ERROR: {e}")
        raise e
    
    end_time = time.time()
    print(f"🌐 HTTP RESPONSE: {response.status_code} in {end_time - start_time:.3f}s")
    print(f"🌐 Response headers: {dict(response.headers)}")
    
    # Log response content (truncated for readability)
    try:
        response_text = response.text
        print(f"🌐 Response size: {len(response_text)} bytes")
        if response.status_code == 200:
            # For successful responses, show first 300 chars
            print(f"🌐 Response content: {response_text[:300]}{'...' if len(response_text) > 300 else ''}")
        else:
            # For error responses, show more details
            print(f"🌐 Response text: {response_text[:500]}{'...' if len(response_text) > 500 else ''}")
    except Exception as e:
        print(f"🌐 Error reading response: {e}")
    
    return response

